// Package trickle is the accounting core of a linear payment stream.
//
// A Stream escrows a fixed Deposit that unlocks linearly between Start and
// End, with an optional Cliff before which nothing is claimable. The package
// holds no coins and reads no clock: every method takes the current unix time
// as an argument, so any realm can embed a Stream and settle it in whatever
// asset it custodies (native coins, GRC20 tokens, points).
//
// Invariant, at every instant and after every operation:
//
//	Withdrawn + Withdrawable(now) + Refundable(now) == Deposit
//
// Typical use from a realm:
//
//	s, err := trickle.New(sender, recipient, amount, start, cliff, end, true)
//	...
//	paid, err := s.Withdraw(now, 0) // 0 = everything claimable
//	toRecipient, toSender, err := s.Cancel(now)
package trickle

package trickle

import (
	"errors"
	"math/bits"
)

// MaxDuration bounds a stream's length (100 years) so timestamps stay sane.
const MaxDuration int64 = 100 * 365 * 24 * 60 * 60

var (
	ErrZeroDeposit   = errors.New("trickle: deposit must be positive")
	ErrBadAddress    = errors.New("trickle: invalid sender or recipient address")
	ErrSelfStream    = errors.New("trickle: sender and recipient must differ")
	ErrBadSchedule   = errors.New("trickle: need 0 <= start <= cliff <= end and start < end")
	ErrTooLong       = errors.New("trickle: duration exceeds 100 years")
	ErrNothingToPay  = errors.New("trickle: nothing to withdraw yet")
	ErrOverWithdraw  = errors.New("trickle: amount exceeds withdrawable balance")
	ErrBadAmount     = errors.New("trickle: amount must not be negative")
	ErrCanceled      = errors.New("trickle: stream already canceled")
	ErrNotCancelable = errors.New("trickle: stream is not cancelable")
	ErrEnded         = errors.New("trickle: stream already fully vested")
)

// Status is the lifecycle phase of a stream at a given time.
type Status int

const (
	Scheduled Status = iota // before Start
	Cliffed                 // started, cliff not reached
	Streaming               // unlocking
	Completed               // fully vested, funds still to withdraw
	Settled                 // fully vested and fully withdrawn
	Canceled                // canceled by a party; both sides paid out
)

func (s Status) String() string {
	switch s {
	case Scheduled:
		return "scheduled"
	case Cliffed:
		return "cliff"
	case Streaming:
		return "streaming"
	case Completed:
		return "completed"
	case Settled:
		return "settled"
	case Canceled:
		return "canceled"
	}
	return "unknown"
}

// Stream is a linear vesting schedule over a fixed deposit.
// Times are unix seconds; amounts are in the smallest unit of the asset.
type Stream struct {
	Sender     address
	Recipient  address
	Deposit    int64
	Start      int64
	Cliff      int64
	End        int64
	Withdrawn  int64
	Cancelable bool
	CanceledAt int64 // 0 while live
	// Refunded is what Cancel returned to the sender.
	Refunded int64
}

// New validates a schedule and returns a fresh stream.
func New(sender, recipient address, deposit, start, cliff, end int64, cancelable bool) (Stream, error) {
	if deposit <= 0 {
		return Stream{}, ErrZeroDeposit
	}
	if !sender.IsValid() || !recipient.IsValid() {
		return Stream{}, ErrBadAddress
	}
	if sender == recipient {
		return Stream{}, ErrSelfStream
	}
	if start < 0 || cliff < start || end < cliff || end <= start {
		return Stream{}, ErrBadSchedule
	}
	if end-start > MaxDuration {
		return Stream{}, ErrTooLong
	}
	return Stream{
		Sender:     sender,
		Recipient:  recipient,
		Deposit:    deposit,
		Start:      start,
		Cliff:      cliff,
		End:        end,
		Cancelable: cancelable,
	}, nil
}

// IsCanceled reports whether Cancel has run.
func (s Stream) IsCanceled() bool { return s.CanceledAt != 0 }

// Vested is the amount unlocked for the recipient at time now, including
// what was already withdrawn. It never decreases and never exceeds Deposit.
// After cancellation it is frozen at the cancellation time.
func (s Stream) Vested(now int64) int64 {
	if s.IsCanceled() {
		return s.Deposit - s.Refunded
	}
	if now < s.Cliff || now <= s.Start {
		return 0
	}
	if now >= s.End {
		return s.Deposit
	}
	return mulDiv(s.Deposit, now-s.Start, s.End-s.Start)
}

// Withdrawable is what the recipient can claim at time now.
func (s Stream) Withdrawable(now int64) int64 {
	return s.Vested(now) - s.Withdrawn
}

// Refundable is what the sender would get back by canceling at time now.
// It is zero for a canceled stream.
func (s Stream) Refundable(now int64) int64 {
	return s.Deposit - s.Refunded - s.Vested(now)
}

// Status returns the lifecycle phase at time now.
func (s Stream) Status(now int64) Status {
	switch {
	case s.IsCanceled():
		return Canceled
	case now < s.Start:
		return Scheduled
	case now < s.Cliff:
		return Cliffed
	case now < s.End:
		return Streaming
	case s.Withdrawn < s.Deposit:
		return Completed
	}
	return Settled
}

// Withdraw records a claim of amount by the recipient and returns the amount
// to pay out. An amount of 0 claims everything withdrawable.
func (s *Stream) Withdraw(now, amount int64) (int64, error) {
	if amount < 0 {
		return 0, ErrBadAmount
	}
	avail := s.Withdrawable(now)
	if avail == 0 {
		return 0, ErrNothingToPay
	}
	if amount == 0 {
		amount = avail
	}
	if amount > avail {
		return 0, ErrOverWithdraw
	}
	s.Withdrawn += amount
	return amount, nil
}

// Cancel stops the stream at time now. It returns what must be paid to the
// recipient (vested but unclaimed) and refunded to the sender (unvested).
// The stream is fully settled afterwards. Cancel does not check Cancelable:
// that flag binds the sender only, so the caller decides who may cancel
// (see CancelBySender).
func (s *Stream) Cancel(now int64) (toRecipient, toSender int64, err error) {
	if s.IsCanceled() {
		return 0, 0, ErrCanceled
	}
	if now >= s.End {
		return 0, 0, ErrEnded
	}
	vested := s.Vested(now)
	toRecipient = vested - s.Withdrawn
	toSender = s.Deposit - vested
	s.Refunded = toSender
	s.Withdrawn = vested
	s.CanceledAt = now
	if s.CanceledAt == 0 {
		s.CanceledAt = 1
	}
	return toRecipient, toSender, nil
}

// CancelBySender is Cancel with the Cancelable flag enforced.
func (s *Stream) CancelBySender(now int64) (toRecipient, toSender int64, err error) {
	if !s.Cancelable {
		return 0, 0, ErrNotCancelable
	}
	return s.Cancel(now)
}

// RatePerDay is the average unlock rate, per 86400 seconds, rounded down.
func (s Stream) RatePerDay() int64 {
	d := s.End - s.Start
	if d <= 86400 {
		return s.Deposit
	}
	return mulDiv(s.Deposit, 86400, d)
}

// mulDiv returns floor(a*b/c) for non-negative a, b and positive c with
// a*b/c <= MaxInt64, using a 128-bit intermediate so a*b cannot overflow.
func mulDiv(a, b, c int64) int64 {
	hi, lo := bits.Mul64(uint64(a), uint64(b))
	q, _ := bits.Div64(hi, lo, uint64(c))
	return int64(q)
}

package trickle

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

const maxPageSize = 50

// Count returns the number of streams ever created.
func Count() int { return streams.Size() }

// Withdrawable returns the ugnot the recipient of stream id can claim now.
func Withdrawable(id uint64) int64 {
	return mustGet(id).Withdrawable(time.Now().Unix())
}

// StreamJSON returns stream id as a JSON object.
func StreamJSON(id uint64) string {
	return mustGet(id).json(time.Now().Unix())
}

// StatsJSON returns realm-wide totals as a JSON object.
func StatsJSON() string {
	return `{"streams":` + strconv.Itoa(streams.Size()) +
		`,"deposited":` + strconv.FormatInt(totalDeposited, 10) +
		`,"paid":` + strconv.FormatInt(totalPaid, 10) +
		`,"refunded":` + strconv.FormatInt(totalRefunded, 10) +
		`,"locked":` + strconv.FormatInt(totalDeposited-totalPaid-totalRefunded, 10) +
		`,"now":` + strconv.FormatInt(time.Now().Unix(), 10) + `}`
}

// LatestJSON returns up to limit streams, newest first, skipping offset,
// as a JSON array.
func LatestJSON(offset, limit int) string {
	now := time.Now().Unix()
	var out []string
	streams.ReverseIterateByOffset(clampOffset(offset), clampLimit(limit), func(_ string, v any) bool {
		out = append(out, v.(*Record).json(now))
		return false
	})
	return "[" + strings.Join(out, ",") + "]"
}

// IncomingJSON returns streams whose recipient is addr, newest first.
func IncomingJSON(addr address, offset, limit int) string {
	return indexJSON(byRecipient, addr, offset, limit)
}

// OutgoingJSON returns streams whose sender is addr, newest first.
func OutgoingJSON(addr address, offset, limit int) string {
	return indexJSON(bySender, addr, offset, limit)
}

func indexJSON(index *avl.Tree, addr address, offset, limit int) string {
	now := time.Now().Unix()
	var out []string
	eachOf(index, addr, clampOffset(offset), clampLimit(limit), func(r *Record) {
		out = append(out, r.json(now))
	})
	return "[" + strings.Join(out, ",") + "]"
}

// eachOf walks the streams indexed under addr, newest first.
func eachOf(index *avl.Tree, addr address, offset, limit int, fn func(*Record)) {
	if !addr.IsValid() {
		return
	}
	prefix := addr.String() + ":"
	i := 0
	// ';' is the byte after ':', so [prefix, addr+";") spans exactly addr's keys.
	index.ReverseIterate(prefix, addr.String()+";", func(key string, _ any) bool {
		if i >= offset+limit {
			return true
		}
		if i >= offset {
			if id, err := seqid.FromString(strings.TrimPrefix(key, prefix)); err == nil {
				if r := get(uint64(id)); r != nil {
					fn(r)
				}
			}
		}
		i++
		return false
	})
}

func clampOffset(offset int) int {
	if offset < 0 {
		return 0
	}
	return offset
}

func clampLimit(limit int) int {
	if limit <= 0 || limit > maxPageSize {
		return maxPageSize
	}
	return limit
}

func (r *Record) json(now int64) string {
	i := func(v int64) string { return strconv.FormatInt(v, 10) }
	return `{"id":` + strconv.FormatUint(r.ID, 10) +
		`,"sender":"` + r.Sender.String() +
		`","recipient":"` + r.Recipient.String() +
		`","deposit":` + i(r.Deposit) +
		`,"start":` + i(r.Start) +
		`,"cliff":` + i(r.Cliff) +
		`,"end":` + i(r.End) +
		`,"withdrawn":` + i(r.Withdrawn) +
		`,"withdrawable":` + i(r.Withdrawable(now)) +
		`,"refunded":` + i(r.Refunded) +
		`,"canceledAt":` + i(r.CanceledAt) +
		`,"cancelable":` + strconv.FormatBool(r.Cancelable) +
		`,"status":"` + r.Status(now).String() +
		`","createdAt":` + i(r.CreatedAt) +
		`,"memo":` + jsonString(r.Memo) + `}`
}

// jsonString quotes s as a JSON string. Memos are validated on entry to be
// UTF-8 without control characters, so only quotes and backslashes need
// escaping.
func jsonString(s string) string {
	s = strings.ReplaceAll(s, `\`, `\\`)
	s = strings.ReplaceAll(s, `"`, `\"`)
	return `"` + s + `"`
}

package trickle

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

const (
	realmPath = "/r/g1a04glq8w6ts7r9yzyznpa99qkzwp8pewcf3aef/trickle"
	pageSize  = 20
	barWidth  = 24
)

// Render serves the realm's pages in gnoweb:
//
//	""               overview and latest streams
//	stream/<id>      one stream
//	account/<addr>   streams sent and received by an address
func Render(path string) string {
	now := time.Now().Unix()
	switch {
	case path == "":
		return renderHome(now)
	case strings.HasPrefix(path, "stream/"):
		id, err := strconv.ParseUint(strings.TrimPrefix(path, "stream/"), 10, 64)
		if err != nil {
			return notFound()
		}
		r := get(id)
		if r == nil {
			return notFound()
		}
		return renderStream(r, now)
	case strings.HasPrefix(path, "account/"):
		addr := address(strings.TrimPrefix(path, "account/"))
		if !addr.IsValid() {
			return notFound()
		}
		return renderAccount(addr, now)
	}
	return notFound()
}

func notFound() string {
	return "# Not found\n\n[Back to Trickle](" + realmPath + ")\n"
}

func renderHome(now int64) string {
	var b strings.Builder
	b.WriteString("# Trickle\n\n")
	b.WriteString("**Money that arrives every second.** Lock GNOT once; it unlocks for the recipient continuously. ")
	b.WriteString("They withdraw whenever they like, and the sender can cancel and take back only what has not unlocked yet.\n\n")
	if appURL != "" {
		b.WriteString("[Open the app](" + appURL + ") · ")
	}
	b.WriteString("[Open a stream](" + realmPath + "$help&func=Create) · ")
	b.WriteString("[Run a payroll](" + realmPath + "$help&func=CreateBatch)\n\n")

	b.WriteString("| Streams | Total locked in | Paid to recipients | Locked now |\n|---|---|---|---|\n")
	b.WriteString("| " + strconv.Itoa(streams.Size()) +
		" | " + gnot(totalDeposited) +
		" | " + gnot(totalPaid) +
		" | " + gnot(totalDeposited-totalPaid-totalRefunded) + " |\n\n")

	b.WriteString("## Latest streams\n\n")
	if streams.Size() == 0 {
		b.WriteString("No streams yet. Be the first.\n")
		return b.String()
	}
	b.WriteString(tableHeader)
	streams.ReverseIterateByOffset(0, pageSize, func(_ string, v any) bool {
		b.WriteString(tableRow(v.(*Record), now))
		return false
	})
	b.WriteString("\nSee your own streams at `" + realmPath + ":account/<your address>`.\n")
	return b.String()
}

func renderAccount(addr address, now int64) string {
	var b strings.Builder
	b.WriteString("# Streams of " + addr.String() + "\n\n[Back to Trickle](" + realmPath + ")\n\n")
	section := func(title string, index *avl.Tree) {
		b.WriteString("## " + title + "\n\n")
		n := 0
		eachOf(index, addr, 0, maxPageSize, func(r *Record) {
			if n == 0 {
				b.WriteString(tableHeader)
			}
			b.WriteString(tableRow(r, now))
			n++
		})
		if n == 0 {
			b.WriteString("None.\n")
		}
		b.WriteString("\n")
	}
	section("Incoming", byRecipient)
	section("Outgoing", bySender)
	return b.String()
}

func renderStream(r *Record, now int64) string {
	id := strconv.FormatUint(r.ID, 10)
	vested := r.Vested(now)
	var b strings.Builder
	b.WriteString("# Stream #" + id + "\n\n[Back to Trickle](" + realmPath + ")\n\n")
	if r.Memo != "" {
		b.WriteString("> " + sanitize.InlineText(r.Memo) + "\n\n")
	}
	b.WriteString("`" + bar(vested, r.Deposit) + "` **" + percent(vested, r.Deposit) + "** unlocked · " + r.Status(now).String() + "\n\n")

	b.WriteString("| | |\n|---|---|\n")
	row := func(k, v string) { b.WriteString("| " + k + " | " + v + " |\n") }
	row("From", accountLink(r.Sender))
	row("To", accountLink(r.Recipient))
	row("Deposit", gnot(r.Deposit))
	row("Unlocked", gnot(vested))
	row("Withdrawn", gnot(r.Withdrawn))
	row("Withdrawable now", "**"+gnot(r.Withdrawable(now))+"**")
	row("Rate", gnot(r.RatePerDay())+" / day")
	row("Start", date(r.Start))
	if r.Cliff != r.Start {
		row("Cliff", date(r.Cliff))
	}
	row("End", date(r.End))
	if r.IsCanceled() {
		row("Canceled", date(r.CanceledAt)+", "+gnot(r.Refunded)+" refunded")
	} else if r.Cancelable {
		row("Cancelable", "yes, by sender or recipient")
	} else {
		row("Cancelable", "no (the recipient may still decline it)")
	}

	if !r.IsCanceled() && r.Withdrawn < r.Deposit {
		b.WriteString("\n[Withdraw](" + realmPath + "$help&func=Withdraw&id=" + id + "&amount=0)")
		if now < r.End {
			b.WriteString(" · [Cancel](" + realmPath + "$help&func=Cancel&id=" + id + ")")
			b.WriteString(" · [Transfer](" + realmPath + "$help&func=Transfer&id=" + id + ")")
		}
		b.WriteString("\n")
	}
	return b.String()
}

const tableHeader = "| # | From | To | Deposit | Unlocked | Status | Memo |\n|---|---|---|---|---|---|---|\n"

func tableRow(r *Record, now int64) string {
	id := strconv.FormatUint(r.ID, 10)
	return "| [#" + id + "](" + realmPath + ":stream/" + id + ")" +
		" | " + accountLink(r.Sender) +
		" | " + accountLink(r.Recipient) +
		" | " + gnot(r.Deposit) +
		" | " + percent(r.Vested(now), r.Deposit) +
		" | " + r.Status(now).String() +
		" | " + sanitize.TableCell(r.Memo) + " |\n"
}

func accountLink(a address) string {
	s := a.String()
	return "[" + s[:8] + "…" + s[len(s)-4:] + "](" + realmPath + ":account/" + s + ")"
}

// gnot formats ugnot as GNOT with up to 6 decimals, trailing zeros trimmed.
func gnot(ugnot int64) string {
	whole := strconv.FormatInt(ugnot/1_000_000, 10)
	frac := strconv.FormatInt(ugnot%1_000_000+1_000_000, 10)[1:]
	frac = strings.TrimRight(frac, "0")
	if frac == "" {
		return whole + " GNOT"
	}
	return whole + "." + frac + " GNOT"
}

func percent(part, total int64) string {
	// part <= total, so tenths of a percent fit after scaling down.
	tenths := int64(float64(part) / float64(total) * 1000)
	return strconv.FormatInt(tenths/10, 10) + "." + strconv.FormatInt(tenths%10, 10) + "%"
}

func bar(part, total int64) string {
	filled := int(float64(part) / float64(total) * barWidth)
	return strings.Repeat("█", filled) + strings.Repeat("░", barWidth-filled)
}

func date(unix int64) string {
	return time.Unix(unix, 0).UTC().Format("2006-01-02 15:04:05") + " UTC"
}

// Package trickle is a payment-streaming realm: lock GNOT once and it
// unlocks for the recipient every second. The recipient withdraws what has
// unlocked whenever they like; the sender can cancel and take back only what
// has not unlocked yet.
//
// Use cases: salaries, grants, vesting with a cliff, subscriptions, escrowed
// freelance work. The schedule math lives in gno.land/p/g1a04glq8w6ts7r9yzyznpa99qkzwp8pewcf3aef/trickle
// and is reusable by any realm.
package trickle

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"gno.land/p/g1a04glq8w6ts7r9yzyznpa99qkzwp8pewcf3aef/trickle"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

const (
	denom      = "ugnot"
	maxMemoLen = 80
	maxBatch   = 50
)

// Record is a stream plus the metadata the realm keeps about it.
type Record struct {
	trickle.Stream
	ID        uint64
	Memo      string
	CreatedAt int64
}

var (
	admin  address
	appURL string

	nextID      seqid.ID
	streams     = avl.NewTree() // seqid -> *Record
	bySender    = avl.NewTree() // addr + ":" + seqid -> nil
	byRecipient = avl.NewTree() // addr + ":" + seqid -> nil

	totalDeposited int64 // ugnot ever locked
	totalPaid      int64 // ugnot paid out to recipients
	totalRefunded  int64 // ugnot returned to senders
)

func init(cur realm) {
	admin = cur.Previous().Address()
}

// Create opens a stream to recipient funded by the ugnot sent with the call.
//
//   - startAt: unix time the stream starts; 0 means now.
//   - cliffSeconds: nothing is withdrawable until this long after the start;
//     at the cliff, everything unlocked so far becomes available at once.
//   - durationSeconds: time from start until the deposit is fully unlocked.
//   - cancelable: whether the sender may cancel and reclaim the locked part.
//
// It returns the new stream ID. Must be called directly by a user
// (gnokey maketx call / a wallet) with -send <amount>ugnot.
func Create(cur realm, recipient address, startAt, cliffSeconds, durationSeconds int64, cancelable bool, memo string) uint64 {
	sender, sent := receivePayment(cur)
	now := time.Now().Unix()
	id := open(now, sender, recipient, sent, startAt, cliffSeconds, durationSeconds, cancelable, memo)
	return id
}

// CreateBatch opens one stream per "address:ugnot" pair in recipients
// (comma separated, at most 50), all on the same schedule: a payroll in a
// single transaction. The ugnot sent must equal the sum of the amounts.
// It returns the new stream IDs, comma separated.
func CreateBatch(cur realm, recipients string, startAt, cliffSeconds, durationSeconds int64, cancelable bool, memo string) string {
	sender, sent := receivePayment(cur)
	now := time.Now().Unix()

	parts := strings.Split(recipients, ",")
	if len(parts) > maxBatch {
		panic("too many recipients: at most " + strconv.Itoa(maxBatch))
	}
	var (
		ids []string
		sum int64
	)
	for _, part := range parts {
		addr, amountStr, ok := strings.Cut(strings.TrimSpace(part), ":")
		if !ok {
			panic(`recipients must look like "g1...:1000000,g1...:2500000"`)
		}
		amount, err := strconv.ParseInt(amountStr, 10, 64)
		if err != nil || amount <= 0 {
			panic("invalid amount for " + strconv.Quote(addr))
		}
		if amount > sent-sum {
			panic("amounts add up to more than the ugnot sent")
		}
		sum += amount
		id := open(now, sender, address(addr), amount, startAt, cliffSeconds, durationSeconds, cancelable, memo)
		ids = append(ids, strconv.FormatUint(id, 10))
	}
	if sum != sent {
		panic("amounts add up to less than the ugnot sent")
	}
	return strings.Join(ids, ",")
}

// Withdraw pays the caller, who must be the stream's recipient, amount ugnot
// out of what has unlocked. An amount of 0 withdraws everything available.
// It returns the amount paid.
func Withdraw(cur realm, id uint64, amount int64) int64 {
	r := mustGet(id)
	caller := cur.Previous().Address()
	if caller != r.Recipient {
		panic("only the recipient can withdraw")
	}
	paid, err := r.Withdraw(time.Now().Unix(), amount)
	if err != nil {
		panic(err)
	}
	totalPaid += paid
	pay(cur, r.Recipient, paid)
	chain.Emit("StreamWithdrawn",
		"id", strconv.FormatUint(id, 10),
		"recipient", r.Recipient.String(),
		"amount", strconv.FormatInt(paid, 10),
	)
	return paid
}

// Cancel stops a stream that has not ended: the recipient is paid everything
// unlocked so far and the sender is refunded the rest. The sender can cancel
// only a cancelable stream; the recipient can always walk away.
func Cancel(cur realm, id uint64) {
	r := mustGet(id)
	caller := cur.Previous().Address()
	now := time.Now().Unix()

	var (
		toRecipient, toSender int64
		err                   error
	)
	switch caller {
	case r.Sender:
		toRecipient, toSender, err = r.CancelBySender(now)
	case r.Recipient:
		toRecipient, toSender, err = r.Cancel(now)
	default:
		panic("only the sender or the recipient can cancel")
	}
	if err != nil {
		panic(err)
	}
	totalPaid += toRecipient
	totalRefunded += toSender
	pay(cur, r.Recipient, toRecipient)
	pay(cur, r.Sender, toSender)
	chain.Emit("StreamCanceled",
		"id", strconv.FormatUint(id, 10),
		"by", caller.String(),
		"toRecipient", strconv.FormatInt(toRecipient, 10),
		"toSender", strconv.FormatInt(toSender, 10),
	)
}

// Transfer hands the right to withdraw from a live stream to another
// address. Only the current recipient can call it.
func Transfer(cur realm, id uint64, to address) {
	r := mustGet(id)
	caller := cur.Previous().Address()
	if caller != r.Recipient {
		panic("only the recipient can transfer a stream")
	}
	if !to.IsValid() {
		panic("invalid address")
	}
	if to == r.Sender || to == r.Recipient {
		panic("new recipient must differ from the sender and the current recipient")
	}
	now := time.Now().Unix()
	if st := r.Status(now); st == trickle.Canceled || st == trickle.Settled {
		panic("stream is finished")
	}
	key := seqid.ID(id).String()
	byRecipient.Remove(r.Recipient.String() + ":" + key)
	byRecipient.Set(to.String()+":"+key, nil)
	r.Recipient = to
	chain.Emit("StreamTransferred",
		"id", strconv.FormatUint(id, 10),
		"from", caller.String(),
		"to", to.String(),
	)
}

// SetAppURL sets the web app link shown by Render. Admin only.
func SetAppURL(cur realm, url string) {
	if cur.Previous().Address() != admin {
		panic("admin only")
	}
	if !strings.HasPrefix(url, "https://") || len(url) > 200 || strings.ContainsAny(url, " ()[]<>\"'\n\r\t") {
		panic("invalid url")
	}
	appURL = url
}

// receivePayment returns the caller and the ugnot attached to the call.
//
// The two checks are a pair. unsafe.OriginSend() describes what the
// transaction attached, not what this realm received: only when the previous
// realm is a plain user call (no intermediate realm, no maketx run script)
// are those coins guaranteed to have landed at this realm's address.
func receivePayment(cur realm) (address, int64) {
	if !cur.Previous().IsUserCall() {
		panic("must be called directly by a user (maketx call)")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom || sent[0].Amount <= 0 {
		panic("send ugnot, and only ugnot, with the call to fund the stream")
	}
	return cur.Previous().Address(), sent[0].Amount
}

func open(now int64, sender, recipient address, amount, startAt, cliffSeconds, durationSeconds int64, cancelable bool, memo string) uint64 {
	if startAt == 0 {
		startAt = now
	}
	if startAt < now {
		panic("start time is in the past")
	}
	if cliffSeconds < 0 || durationSeconds <= 0 || durationSeconds > trickle.MaxDuration || cliffSeconds > durationSeconds {
		panic("need 0 <= cliffSeconds <= durationSeconds <= 100 years, and a positive duration")
	}
	if startAt > now+trickle.MaxDuration {
		panic("start time is too far in the future")
	}
	checkMemo(memo)

	s, err := trickle.New(sender, recipient, amount, startAt, startAt+cliffSeconds, startAt+durationSeconds, cancelable)
	if err != nil {
		panic(err)
	}
	id := nextID.Next()
	key := id.String()
	streams.Set(key, &Record{Stream: s, ID: uint64(id), Memo: memo, CreatedAt: now})
	bySender.Set(sender.String()+":"+key, nil)
	byRecipient.Set(recipient.String()+":"+key, nil)
	totalDeposited += amount

	chain.Emit("StreamCreated",
		"id", strconv.FormatUint(uint64(id), 10),
		"sender", sender.String(),
		"recipient", recipient.String(),
		"amount", strconv.FormatInt(amount, 10),
		"start", strconv.FormatInt(s.Start, 10),
		"cliff", strconv.FormatInt(s.Cliff, 10),
		"end", strconv.FormatInt(s.End, 10),
	)
	return uint64(id)
}

func checkMemo(memo string) {
	if len(memo) > maxMemoLen || !utf8.ValidString(memo) {
		panic("memo must be valid UTF-8 of at most " + strconv.Itoa(maxMemoLen) + " bytes")
	}
	for _, c := range memo {
		if c < 0x20 || c == 0x7f {
			panic("memo must not contain control characters")
		}
	}
}

func pay(cur realm, to address, amount int64) {
	if amount == 0 {
		return
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin(denom, amount)))
}

func get(id uint64) *Record {
	v := streams.Get(seqid.ID(id).String())
	if v == nil {
		return nil
	}
	return v.(*Record)
}

func mustGet(id uint64) *Record {
	r := get(id)
	if r == nil {
		panic("stream " + strconv.FormatUint(id, 10) + " not found")
	}
	return r
}

package trickle

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

const maxPageSize = 50

// Count returns the number of streams ever created.
func Count() int { return streams.Size() }

// Withdrawable returns the ugnot the recipient of stream id can claim now.
func Withdrawable(id uint64) int64 {
	return mustGet(id).Withdrawable(time.Now().Unix())
}

// StreamJSON returns stream id as a JSON object.
func StreamJSON(id uint64) string {
	return mustGet(id).json(time.Now().Unix())
}

// StatsJSON returns realm-wide totals as a JSON object.
func StatsJSON() string {
	return `{"streams":` + strconv.Itoa(streams.Size()) +
		`,"deposited":` + strconv.FormatInt(totalDeposited, 10) +
		`,"paid":` + strconv.FormatInt(totalPaid, 10) +
		`,"refunded":` + strconv.FormatInt(totalRefunded, 10) +
		`,"locked":` + strconv.FormatInt(totalDeposited-totalPaid-totalRefunded, 10) +
		`,"now":` + strconv.FormatInt(time.Now().Unix(), 10) + `}`
}

// LatestJSON returns up to limit streams, newest first, skipping offset,
// as a JSON array.
func LatestJSON(offset, limit int) string {
	now := time.Now().Unix()
	var out []string
	streams.ReverseIterateByOffset(clampOffset(offset), clampLimit(limit), func(_ string, v any) bool {
		out = append(out, v.(*Record).json(now))
		return false
	})
	return "[" + strings.Join(out, ",") + "]"
}

// IncomingJSON returns streams whose recipient is addr, newest first.
func IncomingJSON(addr address, offset, limit int) string {
	return indexJSON(byRecipient, addr, offset, limit)
}

// OutgoingJSON returns streams whose sender is addr, newest first.
func OutgoingJSON(addr address, offset, limit int) string {
	return indexJSON(bySender, addr, offset, limit)
}

func indexJSON(index *avl.Tree, addr address, offset, limit int) string {
	now := time.Now().Unix()
	var out []string
	eachOf(index, addr, clampOffset(offset), clampLimit(limit), func(r *Record) {
		out = append(out, r.json(now))
	})
	return "[" + strings.Join(out, ",") + "]"
}

// eachOf walks the streams indexed under addr, newest first.
func eachOf(index *avl.Tree, addr address, offset, limit int, fn func(*Record)) {
	if !addr.IsValid() {
		return
	}
	prefix := addr.String() + ":"
	i := 0
	// ';' is the byte after ':', so [prefix, addr+";") spans exactly addr's keys.
	index.ReverseIterate(prefix, addr.String()+";", func(key string, _ any) bool {
		if i >= offset+limit {
			return true
		}
		if i >= offset {
			if id, err := seqid.FromString(strings.TrimPrefix(key, prefix)); err == nil {
				if r := get(uint64(id)); r != nil {
					fn(r)
				}
			}
		}
		i++
		return false
	})
}

func clampOffset(offset int) int {
	if offset < 0 {
		return 0
	}
	return offset
}

func clampLimit(limit int) int {
	if limit <= 0 || limit > maxPageSize {
		return maxPageSize
	}
	return limit
}

func (r *Record) json(now int64) string {
	i := func(v int64) string { return strconv.FormatInt(v, 10) }
	return `{"id":` + strconv.FormatUint(r.ID, 10) +
		`,"sender":"` + r.Sender.String() +
		`","recipient":"` + r.Recipient.String() +
		`","deposit":` + i(r.Deposit) +
		`,"start":` + i(r.Start) +
		`,"cliff":` + i(r.Cliff) +
		`,"end":` + i(r.End) +
		`,"withdrawn":` + i(r.Withdrawn) +
		`,"withdrawable":` + i(r.Withdrawable(now)) +
		`,"refunded":` + i(r.Refunded) +
		`,"canceledAt":` + i(r.CanceledAt) +
		`,"cancelable":` + strconv.FormatBool(r.Cancelable) +
		`,"status":"` + r.Status(now).String() +
		`","createdAt":` + i(r.CreatedAt) +
		`,"memo":` + jsonString(r.Memo) + `}`
}

// jsonString quotes s as a JSON string. Memos are validated on entry to be
// UTF-8 without control characters, so only quotes and backslashes need
// escaping.
func jsonString(s string) string {
	s = strings.ReplaceAll(s, `\`, `\\`)
	s = strings.ReplaceAll(s, `"`, `\"`)
	return `"` + s + `"`
}

package trickle

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

const (
	realmPath = "/r/g1a04glq8w6ts7r9yzyznpa99qkzwp8pewcf3aef/trickle"
	pageSize  = 20
	maxPages  = 1 << 20
	barWidth  = 24
)

// Render serves the realm's pages in gnoweb:
//
//	""               overview and latest streams
//	stream/<id>      one stream
//	account/<addr>   streams sent and received by an address
func Render(path string) string {
	now := time.Now().Unix()
	switch {
	case path == "":
		return renderHome(now)
	case strings.HasPrefix(path, "stream/"):
		id, err := strconv.ParseUint(strings.TrimPrefix(path, "stream/"), 10, 64)
		if err != nil {
			return notFound()
		}
		r := get(id)
		if r == nil {
			return notFound()
		}
		return renderStream(r, now)
	case strings.HasPrefix(path, "account/"):
		// account/<addr> or account/<addr>/<page>, pages counted from 1.
		rest, pageStr, paged := strings.Cut(strings.TrimPrefix(path, "account/"), "/")
		page := 1
		if paged {
			n, err := strconv.Atoi(pageStr)
			if err != nil || n < 1 || n > maxPages {
				return notFound()
			}
			page = n
		}
		addr := address(rest)
		if !addr.IsValid() {
			return notFound()
		}
		return renderAccount(addr, page, now)
	}
	return notFound()
}

func notFound() string {
	return "# Not found\n\n[Back to Trickle](" + realmPath + ")\n"
}

func renderHome(now int64) string {
	var b strings.Builder
	b.WriteString("# Trickle\n\n")
	b.WriteString("**Money that arrives every second.** Lock GNOT once; it unlocks for the recipient continuously. ")
	b.WriteString("They withdraw whenever they like, and the sender can cancel and take back only what has not unlocked yet.\n\n")
	if appURL != "" {
		b.WriteString("[Open the app](" + appURL + ") · ")
	}
	b.WriteString("[Open a stream](" + realmPath + "$help&func=Create) · ")
	b.WriteString("[Run a payroll](" + realmPath + "$help&func=CreateBatch)\n\n")

	b.WriteString("| Streams | Total locked in | Paid to recipients | Locked now |\n|---|---|---|---|\n")
	b.WriteString("| " + strconv.Itoa(streams.Size()) +
		" | " + gnot(totalDeposited) +
		" | " + gnot(totalPaid) +
		" | " + gnot(totalDeposited-totalPaid-totalRefunded) + " |\n\n")

	b.WriteString("## Latest streams\n\n")
	if streams.Size() == 0 {
		b.WriteString("No streams yet. Be the first.\n")
		return b.String()
	}
	b.WriteString(tableHeader)
	streams.ReverseIterateByOffset(0, pageSize, func(_ string, v any) bool {
		b.WriteString(tableRow(v.(*Record), now))
		return false
	})
	b.WriteString("\nSee your own streams at `" + realmPath + ":account/<your address>`.\n")
	return b.String()
}

func renderAccount(addr address, page int, now int64) string {
	var b strings.Builder
	b.WriteString("# Streams of " + addr.String() + "\n\n[Back to Trickle](" + realmPath + ")\n\n")
	offset := (page - 1) * maxPageSize
	more := false
	section := func(title string, index *avl.Tree) {
		b.WriteString("## " + title + "\n\n")
		n := 0
		// One extra row tells whether an older page exists.
		eachOf(index, addr, offset, maxPageSize+1, func(r *Record) {
			if n == maxPageSize {
				more = true
				return
			}
			if n == 0 {
				b.WriteString(tableHeader)
			}
			b.WriteString(tableRow(r, now))
			n++
		})
		if n == 0 {
			b.WriteString("None.\n")
		}
		b.WriteString("\n")
	}
	section("Incoming", byRecipient)
	section("Outgoing", bySender)
	base := realmPath + ":account/" + addr.String() + "/"
	if page > 1 {
		b.WriteString("[Newer](" + base + strconv.Itoa(page-1) + ")")
	}
	if more {
		if page > 1 {
			b.WriteString(" · ")
		}
		b.WriteString("[Older](" + base + strconv.Itoa(page+1) + ")")
	}
	b.WriteString("\n")
	return b.String()
}

func renderStream(r *Record, now int64) string {
	id := strconv.FormatUint(r.ID, 10)
	vested := r.Vested(now)
	var b strings.Builder
	b.WriteString("# Stream #" + id + "\n\n[Back to Trickle](" + realmPath + ")\n\n")
	if r.Memo != "" {
		b.WriteString("> " + sanitize.InlineText(r.Memo) + "\n\n")
	}
	b.WriteString("`" + bar(vested, r.Deposit) + "` **" + percent(vested, r.Deposit) + "** unlocked · " + r.Status(now).String() + "\n\n")

	b.WriteString("| | |\n|---|---|\n")
	row := func(k, v string) { b.WriteString("| " + k + " | " + v + " |\n") }
	row("From", accountLink(r.Sender))
	row("To", accountLink(r.Recipient))
	row("Deposit", gnot(r.Deposit))
	row("Unlocked", gnot(vested))
	row("Withdrawn", gnot(r.Withdrawn))
	row("Withdrawable now", "**"+gnot(r.Withdrawable(now))+"**")
	row("Rate", gnot(r.RatePerDay())+" / day")
	row("Start", date(r.Start))
	if r.Cliff != r.Start {
		row("Cliff", date(r.Cliff))
	}
	row("End", date(r.End))
	if r.IsCanceled() {
		row("Canceled", date(r.CanceledAt)+", "+gnot(r.Refunded)+" refunded")
	} else if r.Cancelable {
		row("Cancelable", "yes, by sender or recipient")
	} else {
		row("Cancelable", "no (the recipient may still decline it)")
	}

	if !r.IsCanceled() && r.Withdrawn < r.Deposit {
		b.WriteString("\n[Withdraw](" + realmPath + "$help&func=Withdraw&id=" + id + "&amount=0)")
		b.WriteString(" · [Transfer](" + realmPath + "$help&func=Transfer&id=" + id + ")")
		if now < r.End {
			b.WriteString(" · [Cancel](" + realmPath + "$help&func=Cancel&id=" + id + ")")
		}
		b.WriteString("\n")
	}
	return b.String()
}

const tableHeader = "| # | From | To | Deposit | Unlocked | Status | Memo |\n|---|---|---|---|---|---|---|\n"

func tableRow(r *Record, now int64) string {
	id := strconv.FormatUint(r.ID, 10)
	return "| [#" + id + "](" + realmPath + ":stream/" + id + ")" +
		" | " + accountLink(r.Sender) +
		" | " + accountLink(r.Recipient) +
		" | " + gnot(r.Deposit) +
		" | " + percent(r.Vested(now), r.Deposit) +
		" | " + r.Status(now).String() +
		" | " + sanitize.TableCell(r.Memo) + " |\n"
}

func accountLink(a address) string {
	s := a.String()
	return "[" + s[:8] + "…" + s[len(s)-4:] + "](" + realmPath + ":account/" + s + ")"
}

// gnot formats ugnot as GNOT with up to 6 decimals, trailing zeros trimmed.
func gnot(ugnot int64) string {
	whole := strconv.FormatInt(ugnot/1_000_000, 10)
	frac := strconv.FormatInt(ugnot%1_000_000+1_000_000, 10)[1:]
	frac = strings.TrimRight(frac, "0")
	if frac == "" {
		return whole + " GNOT"
	}
	return whole + "." + frac + " GNOT"
}

func percent(part, total int64) string {
	// part <= total, so tenths of a percent fit after scaling down.
	tenths := int64(float64(part) / float64(total) * 1000)
	return strconv.FormatInt(tenths/10, 10) + "." + strconv.FormatInt(tenths%10, 10) + "%"
}

func bar(part, total int64) string {
	filled := int(float64(part) / float64(total) * barWidth)
	return strings.Repeat("█", filled) + strings.Repeat("░", barWidth-filled)
}

func date(unix int64) string {
	return time.Unix(unix, 0).UTC().Format("2006-01-02 15:04:05") + " UTC"
}

// Package trickle is a payment-streaming realm: lock GNOT once and it
// unlocks for the recipient every second. The recipient withdraws what has
// unlocked whenever they like; the sender can cancel and take back only what
// has not unlocked yet.
//
// Use cases: salaries, grants, vesting with a cliff, subscriptions, escrowed
// freelance work. The schedule math lives in gno.land/p/g1a04glq8w6ts7r9yzyznpa99qkzwp8pewcf3aef/trickle
// and is reusable by any realm.
package trickle

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"crypto/bech32"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"gno.land/p/g1a04glq8w6ts7r9yzyznpa99qkzwp8pewcf3aef/trickle"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

const (
	denom      = "ugnot"
	maxMemoLen = 80
	maxBatch   = 50
)

// Record is a stream plus the metadata the realm keeps about it.
type Record struct {
	trickle.Stream
	ID        uint64
	Memo      string
	CreatedAt int64
}

var (
	admin  address
	appURL string

	nextID      seqid.ID
	streams     = avl.NewTree() // seqid -> *Record
	bySender    = avl.NewTree() // addr + ":" + seqid -> nil
	byRecipient = avl.NewTree() // addr + ":" + seqid -> nil

	totalDeposited int64 // ugnot ever locked
	totalPaid      int64 // ugnot paid out to recipients
	totalRefunded  int64 // ugnot returned to senders
)

func init(cur realm) {
	admin = cur.Previous().Address()
}

// Create opens a stream to recipient funded by the ugnot sent with the call.
//
//   - startAt: unix time the stream starts; 0 means now.
//   - cliffSeconds: nothing is withdrawable until this long after the start;
//     at the cliff, everything unlocked so far becomes available at once.
//   - durationSeconds: time from start until the deposit is fully unlocked.
//   - cancelable: whether the sender may cancel and reclaim the locked part.
//
// It returns the new stream ID. Must be called directly by a user
// (gnokey maketx call / a wallet) with -send <amount>ugnot.
func Create(cur realm, recipient address, startAt, cliffSeconds, durationSeconds int64, cancelable bool, memo string) uint64 {
	sender, sent := receivePayment(cur)
	now := time.Now().Unix()
	id := open(now, sender, recipient, sent, startAt, cliffSeconds, durationSeconds, cancelable, memo)
	return id
}

// CreateBatch opens one stream per "address:ugnot" pair in recipients
// (comma separated, at most 50), all on the same schedule: a payroll in a
// single transaction. The ugnot sent must equal the sum of the amounts.
// It returns the new stream IDs, comma separated.
func CreateBatch(cur realm, recipients string, startAt, cliffSeconds, durationSeconds int64, cancelable bool, memo string) string {
	sender, sent := receivePayment(cur)
	now := time.Now().Unix()

	parts := strings.Split(recipients, ",")
	if len(parts) > maxBatch {
		panic("too many recipients: at most " + strconv.Itoa(maxBatch))
	}
	var (
		ids []string
		sum int64
	)
	for _, part := range parts {
		addr, amountStr, ok := strings.Cut(strings.TrimSpace(part), ":")
		if !ok {
			panic(`recipients must look like "g1...:1000000,g1...:2500000"`)
		}
		amount, err := strconv.ParseInt(amountStr, 10, 64)
		if err != nil || amount <= 0 {
			panic("invalid amount for " + strconv.Quote(addr))
		}
		if amount > sent-sum {
			panic("amounts add up to more than the ugnot sent")
		}
		sum += amount
		id := open(now, sender, address(addr), amount, startAt, cliffSeconds, durationSeconds, cancelable, memo)
		ids = append(ids, strconv.FormatUint(id, 10))
	}
	if sum != sent {
		panic("amounts add up to less than the ugnot sent")
	}
	return strings.Join(ids, ",")
}

// Withdraw pays the caller, who must be the stream's recipient, amount ugnot
// out of what has unlocked. An amount of 0 withdraws everything available.
// It returns the amount paid.
func Withdraw(cur realm, id uint64, amount int64) int64 {
	r := mustGet(id)
	caller := cur.Previous().Address()
	if caller != r.Recipient {
		panic("only the recipient can withdraw")
	}
	paid, err := r.Withdraw(time.Now().Unix(), amount)
	if err != nil {
		panic(err)
	}
	totalPaid += paid
	pay(cur, r.Recipient, paid)
	chain.Emit("StreamWithdrawn",
		"id", strconv.FormatUint(id, 10),
		"recipient", r.Recipient.String(),
		"amount", strconv.FormatInt(paid, 10),
	)
	return paid
}

// Cancel stops a stream that has not ended: the recipient is paid everything
// unlocked so far and the sender is refunded the rest. The sender can cancel
// only a cancelable stream; the recipient can always walk away.
func Cancel(cur realm, id uint64) {
	r := mustGet(id)
	caller := cur.Previous().Address()
	now := time.Now().Unix()

	var (
		toRecipient, toSender int64
		err                   error
	)
	switch caller {
	case r.Sender:
		toRecipient, toSender, err = r.CancelBySender(now)
	case r.Recipient:
		toRecipient, toSender, err = r.Cancel(now)
	default:
		panic("only the sender or the recipient can cancel")
	}
	if err != nil {
		panic(err)
	}
	totalPaid += toRecipient
	totalRefunded += toSender
	pay(cur, r.Recipient, toRecipient)
	pay(cur, r.Sender, toSender)
	chain.Emit("StreamCanceled",
		"id", strconv.FormatUint(id, 10),
		"by", caller.String(),
		"toRecipient", strconv.FormatInt(toRecipient, 10),
		"toSender", strconv.FormatInt(toSender, 10),
	)
}

// Transfer hands the right to withdraw from a live stream to another
// address. Only the current recipient can call it.
func Transfer(cur realm, id uint64, to address) {
	r := mustGet(id)
	caller := cur.Previous().Address()
	if caller != r.Recipient {
		panic("only the recipient can transfer a stream")
	}
	mustBeCanonical(to)
	if to == r.Sender || to == r.Recipient {
		panic("new recipient must differ from the sender and the current recipient")
	}
	now := time.Now().Unix()
	if st := r.Status(now); st == trickle.Canceled || st == trickle.Settled {
		panic("stream is finished")
	}
	key := seqid.ID(id).String()
	byRecipient.Remove(r.Recipient.String() + ":" + key)
	byRecipient.Set(to.String()+":"+key, nil)
	r.Recipient = to
	chain.Emit("StreamTransferred",
		"id", strconv.FormatUint(id, 10),
		"from", caller.String(),
		"to", to.String(),
	)
}

// SetAppURL sets the web app link shown by Render. Admin only.
func SetAppURL(cur realm, url string) {
	if cur.Previous().Address() != admin {
		panic("admin only")
	}
	if !strings.HasPrefix(url, "https://") || len(url) > 200 || strings.ContainsAny(url, " ()[]<>\"'\n\r\t") {
		panic("invalid url")
	}
	appURL = url
}

// receivePayment returns the caller and the ugnot attached to the call.
//
// The two checks are a pair. unsafe.OriginSend() describes what the
// transaction attached, not what this realm received: only when the previous
// realm is a plain user call (no intermediate realm, no maketx run script)
// are those coins guaranteed to have landed at this realm's address.
func receivePayment(cur realm) (address, int64) {
	if !cur.Previous().IsUserCall() {
		panic("must be called directly by a user (maketx call)")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom || sent[0].Amount <= 0 {
		panic("send ugnot, and only ugnot, with the call to fund the stream")
	}
	return cur.Previous().Address(), sent[0].Amount
}

func open(now int64, sender, recipient address, amount, startAt, cliffSeconds, durationSeconds int64, cancelable bool, memo string) uint64 {
	if startAt == 0 {
		startAt = now
	}
	if startAt < now {
		panic("start time is in the past")
	}
	if cliffSeconds < 0 || durationSeconds <= 0 || durationSeconds > trickle.MaxDuration || cliffSeconds > durationSeconds {
		panic("need 0 <= cliffSeconds <= durationSeconds <= 100 years, and a positive duration")
	}
	if startAt > now+trickle.MaxDuration {
		panic("start time is too far in the future")
	}
	checkMemo(memo)
	mustBeCanonical(recipient)

	s, err := trickle.New(sender, recipient, amount, startAt, startAt+cliffSeconds, startAt+durationSeconds, cancelable)
	if err != nil {
		panic(err)
	}
	id := nextID.Next()
	key := id.String()
	streams.Set(key, &Record{Stream: s, ID: uint64(id), Memo: memo, CreatedAt: now})
	bySender.Set(sender.String()+":"+key, nil)
	byRecipient.Set(recipient.String()+":"+key, nil)
	totalDeposited += amount

	chain.Emit("StreamCreated",
		"id", strconv.FormatUint(uint64(id), 10),
		"sender", sender.String(),
		"recipient", recipient.String(),
		"amount", strconv.FormatInt(amount, 10),
		"start", strconv.FormatInt(s.Start, 10),
		"cliff", strconv.FormatInt(s.Cliff, 10),
		"end", strconv.FormatInt(s.End, 10),
	)
	return uint64(id)
}

// mustBeCanonical rejects any spelling of an address other than the one the
// chain reports for a caller. IsValid also accepts an all-uppercase or
// Bech32m spelling, and a stream stored under one of those could never be
// withdrawn, because Withdraw compares against the caller's canonical address.
func mustBeCanonical(a address) {
	if a.IsValid() {
		if hrp, data, err := bech32.DecodeNoLimit(a.String()); err == nil {
			if enc, err := bech32.Encode(hrp, data); err == nil && enc == a.String() {
				return
			}
		}
	}
	panic("invalid address: use the lowercase g1... form")
}

func checkMemo(memo string) {
	if len(memo) > maxMemoLen || !utf8.ValidString(memo) {
		panic("memo must be valid UTF-8 of at most " + strconv.Itoa(maxMemoLen) + " bytes")
	}
	for _, c := range memo {
		if c < 0x20 || c == 0x7f {
			panic("memo must not contain control characters")
		}
	}
}

func pay(cur realm, to address, amount int64) {
	if amount == 0 {
		return
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin(denom, amount)))
}

func get(id uint64) *Record {
	v := streams.Get(seqid.ID(id).String())
	if v == nil {
		return nil
	}
	return v.(*Record)
}

func mustGet(id uint64) *Record {
	r := get(id)
	if r == nil {
		panic("stream " + strconv.FormatUint(id, 10) + " not found")
	}
	return r
}

