package taletree

// Read API for other realms and off-chain clients (`vm/qeval`). Every
// function returns copies; nothing hands out a pointer into state.

// PassageView is a read-only copy of a passage.
type PassageView struct {
	ID       int
	Tale     int
	Parent   int // 0 for the opening
	Author   address
	Choice   string
	Body     string // empty when the passage is hidden
	Depth    int
	Children []int
	Cheers   int
	Tips     int64
	Ending   bool
	Hidden   bool // the passage or one of its ancestors is hidden
	Height   int64
}

// TaleView is a read-only copy of a tale.
type TaleView struct {
	ID       int
	Title    string
	Narrator address
	Root     int
	Passages int
	Endings  int
	Cheers   int
	Locked   bool
	Height   int64
}

// TaleCount returns the number of tales.
func TaleCount() int { return tales.Size() }

// PassageCount returns the number of passages in all tales.
func PassageCount() int { return passages.Size() }

// BardCount returns the number of distinct writers.
func BardCount() int { return bards.Size() }

// TotalTips returns the ugnot forwarded to authors, all time.
func TotalTips() int64 { return totalTips }

// IsPaused reports whether the keeper paused writing.
func IsPaused() bool { return paused }

// GetTale returns a copy of a tale.
func GetTale(id int) (TaleView, bool) {
	if id <= 0 {
		return TaleView{}, false
	}
	t, ok := getTale(seqidOf(id))
	if !ok {
		return TaleView{}, false
	}
	return TaleView{
		ID:       int(t.ID),
		Title:    t.Title,
		Narrator: t.Narrator,
		Root:     int(t.Root),
		Passages: t.Passages,
		Endings:  t.Endings,
		Cheers:   t.Cheers,
		Locked:   t.Locked,
		Height:   t.Height,
	}, true
}

// GetPassage returns a copy of a passage. The body of a hidden passage
// is left out.
func GetPassage(id int) (PassageView, bool) {
	if id <= 0 {
		return PassageView{}, false
	}
	p, ok := getPassage(seqidOf(id))
	if !ok {
		return PassageView{}, false
	}
	visible := isVisible(p)
	v := PassageView{
		ID:     int(p.ID),
		Tale:   int(p.Tale),
		Parent: int(p.Parent),
		Author: p.Author,
		Choice: p.Choice,
		Depth:  p.Depth,
		Cheers: p.Cheers,
		Tips:   p.Tips,
		Ending: p.Ending,
		Hidden: !visible,
		Height: p.Height,
	}
	if visible {
		v.Body = p.Body
	}
	for _, c := range p.Children {
		v.Children = append(v.Children, int(c))
	}
	return v, true
}

// CanonPath returns the passage ids of a tale's canon, from the opening
// to the last passage readers have chosen.
func CanonPath(taleID int) []int {
	if taleID <= 0 {
		return nil
	}
	t, ok := getTale(seqidOf(taleID))
	if !ok {
		return nil
	}
	var ids []int
	for _, p := range canonPath(t) {
		ids = append(ids, int(p.ID))
	}
	return ids
}

// HasCheered reports whether addr cheered a passage.
func HasCheered(passageID int, addr address) bool {
	if passageID <= 0 {
		return false
	}
	return cheers.Has(seqidOf(passageID).Binary() + addr.String())
}

// Package taletree is a realm for collaborative branching stories,
// read and written straight from gnoweb.
//
// Anyone can start a tale. Anyone can add the next passage under any
// passage, as a new choice, or close a path with an ending. Readers
// cheer the passages they like, once per address; the most-cheered
// choice at each step forms the tale's canon, a single read-through
// picked by readers. Tips sent to a passage go straight to its author.
//
// Every passage is a page (":p/<id>") and every choice is a link, so the
// whole library is browsable without any front-end:
//
//	""                home: totals and the list of tales
//	"tale/<id>"       a tale's opening and an outline of its branches
//	"tale/<id>/canon" the canon as one continuous read
//	"p/<id>"          one passage with its choices and actions
//	"bard/<address>"  a writer's profile
//	"bards"           the hall of fame, by cheers received
//
// Writing functions (StartTale, Branch, WriteEnding, Cheer, Tip) take
// the caller from cur.Previous(). Tip forwards the ugnot sent with the
// transaction to the passage author in the same call, so the realm never
// holds funds. Tale narrators and the realm keeper can hide passages
// and lock tales.
package taletree

package taletree

// JSON read API for web clients. Each function returns one JSON
// document as a string, read with a single `vm/qeval` query:
//
//	gnokey query vm/qeval -data 'gno.land/r/<ns>/taletree/v0.PassageJSON(5)'
//
// Hidden passages (and everything under them) are left out exactly as
// on the Render pages. Every list is bounded.

import (
	"strconv"
	"strings"
	"unicode/utf8"

	"gno.land/p/nt/seqid/v0"
)

const (
	maxPageSize   = 50  // tales per TalesJSON page
	maxTreeNodes  = 300 // passages in a TaleJSON outline
	excerptBytes  = 280 // opening excerpt in TalesJSON
	maxFameJSON   = 50
	maxBardRecent = 20
)

// StatsJSON returns realm totals, limits and the keeper.
func StatsJSON() string {
	var b jsonBuf
	b.open('{')
	b.num("tales", tales.Size())
	b.num("passages", passages.Size())
	b.num("bards", bards.Size())
	b.i64("tipsUgnot", totalTips)
	b.flag("paused", paused)
	b.str("keeper", keeper.Owner().String())
	b.key("limits")
	b.open('{')
	b.num("maxChoices", MaxChoices)
	b.num("maxDepth", MaxDepth)
	b.num("minTitle", MinTitleLen)
	b.num("maxTitle", MaxTitleLen)
	b.num("minChoice", MinChoiceLen)
	b.num("maxChoice", MaxChoiceLen)
	b.num("minBody", MinBodyLen)
	b.num("maxBody", MaxBodyLen)
	b.close('}')
	b.close('}')
	return b.String()
}

// TalesJSON returns one page of tales, newest first. page starts at 1.
func TalesJSON(page, size int) string {
	if page < 1 {
		page = 1
	}
	if size < 1 || size > maxPageSize {
		size = maxPageSize
	}
	var b jsonBuf
	b.open('{')
	b.num("total", tales.Size())
	b.num("page", page)
	b.num("size", size)
	b.key("tales")
	b.open('[')
	tales.ReverseIterateByOffset((page-1)*size, size, func(_ string, v any) bool {
		t := v.(*Tale)
		b.elem()
		b.open('{')
		taleFields(&b, t)
		if root, ok := getPassage(t.Root); ok && !root.Hidden {
			b.str("excerpt", excerpt(root.Body, excerptBytes))
		}
		b.close('}')
		return false
	})
	b.close(']')
	b.close('}')
	return b.String()
}

// TaleJSON returns a tale, its opening passage, its canon and an
// outline of its visible passages (breadth first, no bodies).
func TaleJSON(id int) string {
	t, ok := lookupTale(id)
	if !ok {
		return `{"error":"not_found"}`
	}
	var b jsonBuf
	b.open('{')
	b.key("tale")
	b.open('{')
	taleFields(&b, t)
	b.close('}')
	root, ok := getPassage(t.Root)
	if !ok || root.Hidden {
		b.close('}')
		return b.String()
	}
	b.key("opening")
	b.open('{')
	passageFields(&b, root, true)
	b.close('}')
	b.key("canon")
	canonIDs(&b, t)

	b.key("tree")
	b.open('[')
	queue := []*Passage{root}
	n := 0
	truncated := false
	for len(queue) > 0 {
		p := queue[0]
		queue = queue[1:]
		if n >= maxTreeNodes {
			truncated = true
			break
		}
		n++
		b.elem()
		b.open('{')
		passageFields(&b, p, false)
		b.close('}')
		queue = append(queue, visibleChildren(p)...)
	}
	b.close(']')
	b.flag("truncated", truncated)
	b.close('}')
	return b.String()
}

// PassageJSON returns a passage with its tale, the path from the
// opening, the choices under it and the tale's canon.
func PassageJSON(id int) string {
	p, ok := lookupPassage(id)
	if !ok {
		return `{"error":"not_found"}`
	}
	t, _ := getTale(p.Tale)
	var b jsonBuf
	b.open('{')
	b.key("tale")
	b.open('{')
	taleFields(&b, t)
	b.close('}')
	if !isVisible(p) {
		b.key("passage")
		b.open('{')
		b.num("id", int(p.ID))
		b.num("tale", int(p.Tale))
		b.flag("hidden", true)
		if p.Hidden && p.HiddenReason != "" {
			b.str("reason", p.HiddenReason)
		}
		b.close('}')
		b.close('}')
		return b.String()
	}
	b.key("passage")
	b.open('{')
	passageFields(&b, p, true)
	b.close('}')

	b.key("path")
	b.open('[')
	for _, a := range ancestors(p) {
		if a == nil || a.ID == p.ID {
			continue
		}
		b.elem()
		b.open('{')
		b.num("id", int(a.ID))
		b.str("choice", a.Choice)
		b.num("depth", a.Depth)
		b.close('}')
	}
	b.close(']')

	b.key("choices")
	b.open('[')
	for _, c := range visibleChildren(p) {
		b.elem()
		b.open('{')
		passageFields(&b, c, false)
		b.close('}')
	}
	b.close(']')
	b.key("canon")
	canonIDs(&b, t)
	b.close('}')
	return b.String()
}

// CanonJSON returns the canon of a tale with full passages.
func CanonJSON(id int) string {
	t, ok := lookupTale(id)
	if !ok {
		return `{"error":"not_found"}`
	}
	var b jsonBuf
	b.open('{')
	b.key("tale")
	b.open('{')
	taleFields(&b, t)
	b.close('}')
	b.key("passages")
	b.open('[')
	for _, p := range canonPath(t) {
		b.elem()
		b.open('{')
		passageFields(&b, p, true)
		b.close('}')
	}
	b.close(']')
	b.close('}')
	return b.String()
}

// FameJSON returns the bards with the most cheers received.
func FameJSON(limit int) string {
	if limit < 1 || limit > maxFameJSON {
		limit = maxFameJSON
	}
	var b jsonBuf
	b.open('{')
	b.num("total", bards.Size())
	b.key("bards")
	b.open('[')
	n := 0
	fame.Iterate("", "", func(_ string, v any) bool {
		bd, ok := getBard(v.(address))
		if !ok {
			return false
		}
		b.elem()
		b.open('{')
		bardFields(&b, bd)
		b.close('}')
		n++
		return n >= limit
	})
	b.close(']')
	b.close('}')
	return b.String()
}

// BardJSON returns a writer's totals and latest visible passages.
func BardJSON(addr string) string {
	a := address(addr)
	if !a.IsValid() {
		return `{"error":"invalid_address"}`
	}
	var b jsonBuf
	b.open('{')
	bd, ok := getBard(a)
	if !ok {
		b.str("addr", a.String())
		b.str("name", bardName(a))
		b.key("bard")
		b.raw("null")
		b.close('}')
		return b.String()
	}
	b.str("addr", a.String())
	b.str("name", bardName(a))
	b.key("bard")
	b.open('{')
	bardFields(&b, bd)
	b.close('}')
	b.key("passages")
	b.open('[')
	n := 0
	bardPassages.ReverseIterate(a.String()+"/", a.String()+"0", func(_ string, v any) bool {
		p, ok := getPassage(v.(seqid.ID))
		if !ok || !isVisible(p) {
			return false
		}
		t, _ := getTale(p.Tale)
		b.elem()
		b.open('{')
		passageFields(&b, p, false)
		b.str("taleTitle", t.Title)
		b.close('}')
		n++
		return n >= maxBardRecent
	})
	b.close(']')
	b.close('}')
	return b.String()
}

// ----- field writers -----

func taleFields(b *jsonBuf, t *Tale) {
	hidden := false
	if root, ok := getPassage(t.Root); !ok || root.Hidden {
		hidden = true
	}
	b.num("id", int(t.ID))
	if hidden {
		b.str("title", "")
	} else {
		b.str("title", t.Title)
	}
	b.str("narrator", t.Narrator.String())
	b.str("narratorName", bardName(t.Narrator))
	b.num("root", int(t.Root))
	b.num("passages", t.Passages)
	b.num("endings", t.Endings)
	b.num("cheers", t.Cheers)
	b.flag("locked", t.Locked)
	b.flag("hidden", hidden)
	b.i64("height", t.Height)
	b.i64("created", t.CreatedAt.Unix())
	b.i64("updated", t.UpdatedAt.Unix())
}

// passageFields writes a visible passage. withBody adds the body.
func passageFields(b *jsonBuf, p *Passage, withBody bool) {
	b.num("id", int(p.ID))
	b.num("tale", int(p.Tale))
	b.num("parent", int(p.Parent))
	b.str("author", p.Author.String())
	b.str("authorName", bardName(p.Author))
	b.str("choice", p.Choice)
	if withBody {
		b.str("body", p.Body)
	}
	b.num("depth", p.Depth)
	b.num("cheers", p.Cheers)
	b.i64("tipsUgnot", p.Tips)
	b.flag("ending", p.Ending)
	b.num("choices", len(visibleChildren(p)))
	b.num("slots", MaxChoices-len(p.Children))
	b.i64("height", p.Height)
	b.i64("created", p.CreatedAt.Unix())
}

func bardFields(b *jsonBuf, bd *Bard) {
	b.str("addr", bd.Addr.String())
	b.str("name", bardName(bd.Addr))
	b.num("passages", bd.Passages)
	b.num("tales", bd.Tales)
	b.num("cheers", bd.Cheers)
	b.i64("tipsUgnot", bd.Tips)
}

func canonIDs(b *jsonBuf, t *Tale) {
	b.open('[')
	for _, p := range canonPath(t) {
		b.elem()
		b.raw(strconv.Itoa(int(p.ID)))
	}
	b.close(']')
}

func lookupTale(id int) (*Tale, bool) {
	if id <= 0 {
		return nil, false
	}
	return getTale(seqidOf(id))
}

func lookupPassage(id int) (*Passage, bool) {
	if id <= 0 {
		return nil, false
	}
	return getPassage(seqidOf(id))
}

// excerpt cuts s to at most max bytes on a rune boundary.
func excerpt(s string, max int) string {
	if len(s) <= max {
		return s
	}
	cut := max
	for cut > 0 && !utf8.RuneStart(s[cut]) {
		cut--
	}
	return strings.TrimSpace(s[:cut]) + "…"
}

// ----- a tiny JSON writer -----

// jsonBuf writes JSON objects and arrays. It tracks whether a comma is
// needed before the next member or element.
type jsonBuf struct {
	sb    strings.Builder
	first bool // nothing written yet in the current container
}

func (b *jsonBuf) String() string { return b.sb.String() }

func (b *jsonBuf) open(c byte) {
	b.sb.WriteByte(c)
	b.first = true
}

func (b *jsonBuf) close(c byte) {
	b.sb.WriteByte(c)
	b.first = false
}

// elem starts an array element.
func (b *jsonBuf) elem() {
	if !b.first {
		b.sb.WriteByte(',')
	}
	b.first = false
}

// key starts an object member.
func (b *jsonBuf) key(k string) {
	b.elem()
	writeJSONString(&b.sb, k)
	b.sb.WriteByte(':')
	b.first = false
}

func (b *jsonBuf) raw(s string) {
	b.sb.WriteString(s)
	b.first = false
}

func (b *jsonBuf) str(k, v string) {
	b.key(k)
	writeJSONString(&b.sb, v)
}

func (b *jsonBuf) num(k string, v int) {
	b.key(k)
	b.sb.WriteString(strconv.Itoa(v))
}

func (b *jsonBuf) i64(k string, v int64) {
	b.key(k)
	b.sb.WriteString(strconv.FormatInt(v, 10))
}

func (b *jsonBuf) flag(k string, v bool) {
	b.key(k)
	b.sb.WriteString(strconv.FormatBool(v))
}

const hexDigits = "0123456789abcdef"

// writeJSONString writes s as a JSON string. Control characters, quotes
// and backslashes are escaped; so are <, > and & (as in Go's
// encoding/json), so the output is also safe to embed in HTML. Invalid
// UTF-8 becomes U+FFFD.
func writeJSONString(sb *strings.Builder, s string) {
	sb.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"':
			sb.WriteString(`\"`)
		case r == '\\':
			sb.WriteString(`\\`)
		case r == '\n':
			sb.WriteString(`\n`)
		case r == '\r':
			sb.WriteString(`\r`)
		case r == '\t':
			sb.WriteString(`\t`)
		case r < 0x20 || r == '<' || r == '>' || r == '&' || r == 0x2028 || r == 0x2029:
			sb.WriteString(`\u`)
			sb.WriteByte(hexDigits[(r>>12)&0xf])
			sb.WriteByte(hexDigits[(r>>8)&0xf])
			sb.WriteByte(hexDigits[(r>>4)&0xf])
			sb.WriteByte(hexDigits[r&0xf])
		default:
			sb.WriteRune(r) // range yields U+FFFD for invalid bytes
		}
	}
	sb.WriteByte('"')
}

package taletree

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/avl/pager/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mux/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/sys/users"
)

const (
	talesPerPage    = 10
	outlineDepth    = 3 // levels shown in a tale outline
	breadcrumbTail  = 3 // last passages shown in a long breadcrumb
	bardPassageList = 10
	fameListSize    = 20
	tipButtonUgnot  = 1_000_000
)

var (
	router *mux.Router
	base   string       // realm path as gnoweb links it, e.g. /r/<ns>/taletree/v0
	tx     txlink.Realm // action links always point at this realm
)

func init() {
	pkgPath := unsafe.CurrentRealm().PkgPath()
	base = strings.TrimPrefix(pkgPath, runtime.ChainDomain())
	tx = txlink.Realm(pkgPath)

	router = mux.NewRouter()
	router.HandleFunc("", renderHome)
	router.HandleFunc("tale/{id}", renderTale)
	router.HandleFunc("tale/{id}/canon", renderCanon)
	router.HandleFunc("p/{id}", renderPassage)
	router.HandleFunc("bard/{addr}", renderBard)
	router.HandleFunc("bards", renderFame)
	router.SetNotFoundHandler(func(res *mux.ResponseWriter, req *mux.Request) {
		res.Write("# Page not found\n\nNo page at `" + sanitize.InlineText(req.Path) + "`. [Back to Taletree](" + base + ")\n")
	})
}

// Render serves every Taletree page; see the package doc for routes.
func Render(path string) string {
	return router.Render(path)
}

// ----- pages -----

func renderHome(res *mux.ResponseWriter, req *mux.Request) {
	res.Write("# 🌳 Taletree\n\n")
	res.Write("*Stories that branch. You write what happens next.*\n\n")
	res.Write("Taletree is a library of choose-your-own-adventure tales written together, on-chain. " +
		"Start a tale, add a new choice under any passage, or close a path with an ending. " +
		"Cheer the passages you love: the most-cheered choice at each step becomes the tale's **canon**. " +
		"Tips go straight to the author.\n\n")

	if paused {
		res.Write("> [!WARNING]\n> Writing is paused by the keeper. Reading, cheering and tipping still work.\n\n")
	}

	res.Write(count(tales.Size(), "tale") + " · " + count(passages.Size(), "passage") + " · " +
		count(bards.Size(), "bard") + " · **" + gnot(totalTips) + "** tipped to authors\n\n")

	res.Write(button(tx.Call("StartTale"), "✍️ Start a tale", "") + " " +
		button(base+":bards", "🏆 Hall of fame", "outline") + "\n\n")

	res.Write("## Tales\n\n")
	if tales.Size() == 0 {
		res.Write("No tale yet. Be the first to [start one](" + tx.Call("StartTale") + ").\n\n")
	} else {
		pg := pager.NewPager(&tales, talesPerPage, true)
		page, err := pg.GetPageByPath(req.RawPath)
		if err != nil {
			res.Write("Invalid page.\n")
			return
		}
		for _, item := range page.Items {
			t := item.Value.(*Tale)
			lock := ""
			if t.Locked {
				lock = " 🔒"
			}
			title := sanitize.InlineText(t.Title)
			if root, ok := getPassage(t.Root); !ok || root.Hidden {
				title = "Hidden tale"
			}
			res.Write(ufmt.Sprintf("- **[%s](%s:tale/%d)**%s by %s · %s · %s · 🍻 %d · updated %s\n",
				title, base, uint64(t.ID), lock, bardLink(t.Narrator),
				plural(t.Passages, "passage"), plural(t.Endings, "ending"), t.Cheers, t.UpdatedAt.UTC().Format("2006-01-02")))
		}
		if picker := page.Picker(req.Path); picker != "" {
			res.Write("\n" + picker + "\n")
		}
		res.Write("\n")
	}

	res.Write("## How it works\n\n")
	res.Write("1. **Read**: open a tale, follow the choices, or read its canon in one go.\n")
	res.Write("2. **Write**: under any passage, add a choice and what happens next (20 to 1,500 characters), or write an ending.\n")
	res.Write("3. **Cheer**: one cheer per passage per account. The most-cheered choice at each step is the canon.\n")
	res.Write("4. **Tip**: send GNOT to a passage you liked; all of it goes to the author in the same transaction.\n\n")
	res.Write(ufmt.Sprintf("Each passage has up to %d choices and a tale goes up to %d passages deep. "+
		"Narrators can hide passages in their tale and lock it when it is finished.\n", MaxChoices, MaxDepth))
}

func renderTale(res *mux.ResponseWriter, req *mux.Request) {
	t, ok := taleFromVar(req.GetVar("id"))
	if !ok {
		notFound(res, "tale")
		return
	}
	root, _ := getPassage(t.Root)

	res.Write(crumbs(link("Taletree", base)) + "\n\n")
	res.Write("# " + sanitize.InlineText(t.Title) + "\n\n")
	res.Write(ufmt.Sprintf("Narrated by %s · %s · %s · 🍻 %s",
		bardLink(t.Narrator), plural(t.Passages, "passage"), plural(t.Endings, "ending"), plural(t.Cheers, "cheer")))
	if t.Locked {
		res.Write(" · 🔒 locked")
	}
	res.Write("\n\n")

	if root.Hidden {
		res.Write("> [!CAUTION]\n> This tale was hidden by a moderator.\n")
		return
	}

	res.Write(sanitize.Block(root.Body))
	res.Write(button(ufmt.Sprintf("%s:p/%d", base, uint64(root.ID)), "📖 Start reading", "") + " " +
		button(ufmt.Sprintf("%s:tale/%d/canon", base, uint64(t.ID)), "✨ Read the canon", "outline") + "\n\n")

	res.Write("## Map of the tale\n\n")
	if len(root.Children) == 0 {
		res.Write("No choice yet. [Write the first one](" + branchLink(root) + ").\n")
		return
	}
	res.Write("Every branch, " + strconv.Itoa(outlineDepth) + " levels deep. ✨ marks the canon, 🏁 an ending.\n\n")
	canon := map[seqid.ID]bool{}
	for _, p := range canonPath(t) {
		canon[p.ID] = true
	}
	writeOutline(res, root, 0, canon)
}

func writeOutline(res *mux.ResponseWriter, p *Passage, level int, canon map[seqid.ID]bool) {
	indent := strings.Repeat("  ", level)
	for _, cid := range p.Children {
		c, ok := getPassage(cid)
		if !ok || c.Hidden {
			continue
		}
		marks := ""
		if canon[c.ID] {
			marks += " ✨"
		}
		if c.Ending {
			marks += " 🏁"
		}
		res.Write(ufmt.Sprintf("%s- [%s](%s:p/%d) · 🍻 %d%s",
			indent, sanitize.InlineText(c.Choice), base, uint64(c.ID), c.Cheers, marks))
		if level+1 >= outlineDepth {
			if n := len(visibleChildren(c)); n > 0 {
				res.Write(ufmt.Sprintf(" · *%d more choices below*", n))
			}
			res.Write("\n")
			continue
		}
		res.Write("\n")
		writeOutline(res, c, level+1, canon)
	}
}

func renderCanon(res *mux.ResponseWriter, req *mux.Request) {
	t, ok := taleFromVar(req.GetVar("id"))
	if !ok {
		notFound(res, "tale")
		return
	}
	path := canonPath(t)
	res.Write(crumbs(link("Taletree", base), link(sanitize.InlineText(t.Title), ufmt.Sprintf("%s:tale/%d", base, uint64(t.ID)))) + "\n\n")
	res.Write("# " + sanitize.InlineText(t.Title) + ": the canon\n\n")
	if len(path) == 0 {
		res.Write("> [!CAUTION]\n> This tale was hidden by a moderator.\n")
		return
	}
	res.Write("*The path readers cheered most, one passage after another.*\n\n")
	for i, p := range path {
		if i > 0 {
			res.Write(ufmt.Sprintf("### → [%s](%s:p/%d)\n", sanitize.InlineText(p.Choice), base, uint64(p.ID)))
		}
		res.Write(sanitize.Block(p.Body))
		res.Write(ufmt.Sprintf("*%s · 🍻 %d*\n\n", bardLink(p.Author), p.Cheers))
	}
	last := path[len(path)-1]
	if last.Ending {
		res.Write("## 🏁 The End\n\n")
		res.Write("Not your ending? [Explore the other branches](" + ufmt.Sprintf("%s:tale/%d", base, uint64(t.ID)) + ").\n")
		return
	}
	res.Write("---\n\n*The canon continues when someone writes what happens next.*\n\n")
	if !t.Locked {
		res.Write(button(branchLink(last), "✍️ Write what happens next", "") + "\n")
	}
}

func renderPassage(res *mux.ResponseWriter, req *mux.Request) {
	p, ok := passageFromVar(req.GetVar("id"))
	if !ok {
		notFound(res, "passage")
		return
	}
	t, _ := getTale(p.Tale)
	taleURL := ufmt.Sprintf("%s:tale/%d", base, uint64(t.ID))

	res.Write(breadcrumb(p, t) + "\n\n")
	if !isVisible(p) {
		res.Write("# Hidden passage\n\n")
		reason := ""
		if p.Hidden && p.HiddenReason != "" {
			reason = " Reason: " + sanitize.InlineText(p.HiddenReason)
		}
		res.Write("> [!CAUTION]\n> This passage, or one before it, was hidden by a moderator." + reason + "\n\n")
		res.Write("[Back to the tale](" + taleURL + ")\n")
		return
	}

	if p.Depth == 0 {
		res.Write("# " + sanitize.InlineText(t.Title) + "\n\n")
	} else {
		res.Write("# " + sanitize.InlineText(p.Choice) + "\n\n")
	}
	res.Write(sanitize.Block(p.Body))

	meta := ufmt.Sprintf("Written by %s · block %d · 🍻 %d", bardLink(p.Author), p.Height, p.Cheers)
	if p.Tips > 0 {
		meta += " · 💰 " + gnot(p.Tips)
	}
	res.Write("*" + meta + "*\n\n")

	if p.Ending {
		res.Write("## 🏁 The End\n\n")
		res.Write("This path ends here. [Read the canon](" + taleURL + "/canon) or [explore other branches](" + taleURL + ").\n\n")
	} else {
		res.Write("## What happens next?\n\n")
		kids := visibleChildren(p)
		if len(kids) == 0 {
			res.Write("*Nobody has written it yet. It could be you.*\n\n")
		}
		canon := map[seqid.ID]bool{}
		for _, c := range canonPath(t) {
			canon[c.ID] = true
		}
		for i, c := range kids {
			marks := ""
			if canon[c.ID] {
				marks += " · ✨ canon"
			}
			if c.Ending {
				marks += " · 🏁 ending"
			}
			res.Write(ufmt.Sprintf("%d. **[%s](%s:p/%d)** · 🍻 %d%s\n",
				i+1, sanitize.InlineText(c.Choice), base, uint64(c.ID), c.Cheers, marks))
		}
		res.Write("\n")
	}

	actions := []string{}
	if !p.Ending && !t.Locked && !paused && len(p.Children) < MaxChoices {
		actions = append(actions,
			button(branchLink(p), "✍️ Add a choice", ""),
			button(tx.NewLink("WriteEnding").AddArgs("parentID", strconv.Itoa(int(p.ID))).URL(), "🏁 Write an ending", "outline"))
	}
	actions = append(actions,
		button(tx.NewLink("Cheer").AddArgs("passageID", strconv.Itoa(int(p.ID))).URL(), "🍻 Cheer", "outline"),
		button(tx.NewLink("Tip").AddArgs("passageID", strconv.Itoa(int(p.ID))).SetSend(strconv.Itoa(tipButtonUgnot)+"ugnot").URL(), "💰 Tip 1 GNOT", "outline"))
	res.Write(strings.Join(actions, " ") + "\n\n")

	if p.Parent != 0 {
		res.Write(ufmt.Sprintf("[← Previous passage](%s:p/%d) · ", base, uint64(p.Parent)))
	}
	res.Write("[Map of the tale](" + taleURL + ")\n")
}

func renderBard(res *mux.ResponseWriter, req *mux.Request) {
	addr := address(req.GetVar("addr"))
	if !addr.IsValid() {
		notFound(res, "bard")
		return
	}
	res.Write(crumbs(link("Taletree", base), link("Hall of fame", base+":bards")) + "\n\n")
	res.Write("# " + bardName(addr) + "\n\n")
	if name := bardName(addr); name != addr.String() {
		res.Write("`" + addr.String() + "`\n\n")
	}
	b, ok := getBard(addr)
	if !ok {
		res.Write("This address has not written anything yet.\n")
		return
	}
	res.Write(count(b.Passages, "passage") + " · " + count(b.Tales, "tale") + " started · 🍻 " +
		count(b.Cheers, "cheer") + " received · 💰 **" + gnot(b.Tips) + "** received in tips\n\n")

	res.Write("## Latest passages\n\n")
	prefix := addr.String() + "/"
	n := 0
	// "0" sorts right after "/" so [prefix, addr+"0") holds this bard's keys only.
	bardPassages.ReverseIterate(prefix, addr.String()+"0", func(_ string, v any) bool {
		p, ok := getPassage(v.(seqid.ID))
		if !ok || !isVisible(p) {
			return false
		}
		t, _ := getTale(p.Tale)
		label := sanitize.InlineText(p.Choice)
		if p.Depth == 0 {
			label = "Opening of " + sanitize.InlineText(t.Title)
		}
		res.Write(ufmt.Sprintf("- [%s](%s:p/%d) in *%s* · 🍻 %d\n",
			label, base, uint64(p.ID), sanitize.InlineText(t.Title), p.Cheers))
		n++
		return n >= bardPassageList
	})
	if n == 0 {
		res.Write("Nothing to show.\n")
	}
}

func renderFame(res *mux.ResponseWriter, req *mux.Request) {
	res.Write(crumbs(link("Taletree", base)) + "\n\n")
	res.Write("# 🏆 Hall of fame\n\n")
	res.Write("Bards ranked by cheers received on their passages.\n\n")
	if fame.Size() == 0 {
		res.Write("No bard yet.\n")
		return
	}
	res.Write("| # | Bard | Cheers | Passages | Tips received |\n|---:|---|---:|---:|---:|\n")
	rank := 0
	fame.Iterate("", "", func(_ string, v any) bool {
		b, _ := getBard(v.(address))
		rank++
		res.Write(ufmt.Sprintf("| %d | %s | %d | %d | %s |\n", rank, bardLink(b.Addr), b.Cheers, b.Passages, gnot(b.Tips)))
		return rank >= fameListSize
	})
}

// ----- helpers -----

func taleFromVar(s string) (*Tale, bool) {
	id, err := strconv.ParseUint(s, 10, 64)
	if err != nil || id == 0 {
		return nil, false
	}
	return getTale(seqid.ID(id))
}

func passageFromVar(s string) (*Passage, bool) {
	id, err := strconv.ParseUint(s, 10, 64)
	if err != nil || id == 0 {
		return nil, false
	}
	return getPassage(seqid.ID(id))
}

func visibleChildren(p *Passage) []*Passage {
	var kids []*Passage
	for _, cid := range p.Children {
		if c, ok := getPassage(cid); ok && !c.Hidden {
			kids = append(kids, c)
		}
	}
	return kids
}

// breadcrumb shows the way from the opening to p. Long paths keep the
// opening and the last few steps.
func breadcrumb(p *Passage, t *Tale) string {
	items := []string{link("Taletree", base), link(sanitize.InlineText(t.Title), ufmt.Sprintf("%s:tale/%d", base, uint64(t.ID)))}
	path := ancestors(p)
	start := 1
	if len(path)-1 > breadcrumbTail {
		start = len(path) - breadcrumbTail
		items = append(items, "…")
	}
	for i := start; i < len(path); i++ {
		a := path[i]
		if a == nil {
			continue
		}
		if a.ID == p.ID {
			items = append(items, sanitize.InlineText(a.Choice))
		} else {
			items = append(items, link(sanitize.InlineText(a.Choice), ufmt.Sprintf("%s:p/%d", base, uint64(a.ID))))
		}
	}
	return crumbs(items...)
}

func crumbs(items ...string) string {
	return strings.Join(items, " › ")
}

func link(text, url string) string {
	return "[" + text + "](" + url + ")"
}

func button(href, label, variant string) string {
	if variant != "" {
		return `<gno-button href="` + href + `" label="` + label + `" variant="` + variant + `" />`
	}
	return `<gno-button href="` + href + `" label="` + label + `" />`
}

func branchLink(p *Passage) string {
	return tx.NewLink("Branch").AddArgs("parentID", strconv.Itoa(int(p.ID))).URL()
}

// plural writes "1 tale", "2 tales".
func plural(n int, word string) string {
	if n == 1 {
		return "1 " + word
	}
	return strconv.Itoa(n) + " " + word + "s"
}

// count is plural with the number in bold.
func count(n int, word string) string {
	p := plural(n, word)
	return "**" + strconv.Itoa(n) + "**" + p[len(strconv.Itoa(n)):]
}

func notFound(res *mux.ResponseWriter, what string) {
	res.Write("# Not found\n\nThere is no such " + what + ". [Back to Taletree](" + base + ")\n")
}

// bardName is the registered username of addr (from r/sys/users), or
// the address itself.
func bardName(addr address) string {
	if u := users.ResolveAddress(addr); u != nil && !u.IsDeleted() {
		return "@" + u.Name()
	}
	return addr.String()
}

func bardLink(addr address) string {
	name := bardName(addr)
	if !strings.HasPrefix(name, "@") {
		s := addr.String()
		if len(s) > 14 {
			name = s[:8] + "…" + s[len(s)-4:]
		}
	}
	return "[" + name + "](" + base + ":bard/" + addr.String() + ")"
}

// gnot formats an ugnot amount as GNOT with up to 2 decimals.
func gnot(ugnot int64) string {
	whole := ugnot / 1_000_000
	cents := (ugnot % 1_000_000) / 10_000
	if cents == 0 {
		return strconv.FormatInt(whole, 10) + " GNOT"
	}
	c := strconv.FormatInt(cents, 10)
	if cents < 10 {
		c = "0" + c
	}
	c = strings.TrimRight(c, "0")
	return strconv.FormatInt(whole, 10) + "." + c + " GNOT"
}

package taletree

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

// Limits. They keep every transaction and every Render bounded.
const (
	MaxChoices   = 8    // choices under one passage
	MaxDepth     = 64   // passages from the opening to the deepest page
	MinTitleLen  = 3    // bytes
	MaxTitleLen  = 80   // bytes
	MinChoiceLen = 3    // bytes
	MaxChoiceLen = 80   // bytes
	MinBodyLen   = 20   // bytes
	MaxBodyLen   = 1500 // bytes
	MaxReasonLen = 140  // bytes
)

// Tale is one story: an opening passage and every branch grown from it.
type Tale struct {
	ID        seqid.ID
	Title     string
	Narrator  address // who started it; can hide passages and lock the tale
	Root      seqid.ID
	Passages  int // including the opening
	Endings   int
	Cheers    int
	Locked    bool
	Height    int64
	CreatedAt time.Time
	UpdatedAt time.Time // last passage written
}

// Passage is one page of a tale.
type Passage struct {
	ID           seqid.ID
	Tale         seqid.ID
	Parent       seqid.ID // 0 for the opening
	Author       address
	Choice       string // link text that leads here; empty for the opening
	Body         string
	Depth        int // 0 for the opening
	Children     []seqid.ID
	Cheers       int
	Tips         int64 // ugnot forwarded to the author
	Ending       bool
	Hidden       bool
	HiddenReason string
	Height       int64
	CreatedAt    time.Time
}

// Bard holds the totals of one writer.
type Bard struct {
	Addr     address
	Passages int
	Tales    int   // tales started
	Cheers   int   // cheers received
	Tips     int64 // ugnot received
}

var (
	taleSeq    seqid.ID
	passageSeq seqid.ID

	tales        avl.Tree // tale id (binary) -> *Tale
	passages     avl.Tree // passage id (binary) -> *Passage
	cheers       avl.Tree // passage id (binary) + address -> true
	bards        avl.Tree // address -> *Bard
	bardPassages avl.Tree // address + "/" + passage id (binary) -> seqid.ID
	fame         avl.Tree // fameKey(cheers, address) -> address

	totalTips int64 // ugnot forwarded to authors, all time
	paused    bool
)

func getTale(id seqid.ID) (*Tale, bool) {
	v := tales.Get(id.Binary())
	if v == nil {
		return nil, false
	}
	return v.(*Tale), true
}

func getPassage(id seqid.ID) (*Passage, bool) {
	v := passages.Get(id.Binary())
	if v == nil {
		return nil, false
	}
	return v.(*Passage), true
}

func mustGetTale(id int) *Tale {
	if id <= 0 {
		panic(ErrTaleNotFound)
	}
	t, ok := getTale(seqidOf(id))
	if !ok {
		panic(ErrTaleNotFound)
	}
	return t
}

func mustGetPassage(id int) *Passage {
	if id <= 0 {
		panic(ErrPassageNotFound)
	}
	p, ok := getPassage(seqidOf(id))
	if !ok {
		panic(ErrPassageNotFound)
	}
	return p
}

// mustGetVisiblePassage returns a passage that is neither hidden nor
// under a hidden passage.
func mustGetVisiblePassage(id int) *Passage {
	p := mustGetPassage(id)
	if !isVisible(p) {
		panic(ErrPassageHidden)
	}
	return p
}

// isVisible reports whether p and all its ancestors are not hidden.
// The walk is bounded by MaxDepth.
func isVisible(p *Passage) bool {
	for p != nil {
		if p.Hidden {
			return false
		}
		if p.Parent == 0 {
			return true
		}
		parent, ok := getPassage(p.Parent)
		if !ok {
			return false
		}
		p = parent
	}
	return false
}

// bardOf returns the record of addr, creating it if needed.
func bardOf(addr address) *Bard {
	if v := bards.Get(addr.String()); v != nil {
		return v.(*Bard)
	}
	b := &Bard{Addr: addr}
	bards.Set(addr.String(), b)
	setFame(b, 0)
	return b
}

func getBard(addr address) (*Bard, bool) {
	v := bards.Get(addr.String())
	if v == nil {
		return nil, false
	}
	return v.(*Bard), true
}

// fameKey sorts bards by cheers received, most first, then by address.
// Cheers are inverted and zero-padded so a forward iteration of the
// fame tree is the hall of fame.
func fameKey(cheers int, addr address) string {
	inv := strconv.Itoa(999999999 - cheers)
	return strings.Repeat("0", 9-len(inv)) + inv + "/" + addr.String()
}

// setFame moves b to its new place in the fame index.
func setFame(b *Bard, newCheers int) {
	fame.Remove(fameKey(b.Cheers, b.Addr))
	b.Cheers = newCheers
	fame.Set(fameKey(b.Cheers, b.Addr), b.Addr)
}

func bardPassageKey(addr address, id seqid.ID) string {
	return addr.String() + "/" + id.Binary()
}

// cleanLine trims a one-line field (title, choice) and folds inner
// newlines and tabs to spaces.
func cleanLine(s string) string {
	s = strings.TrimSpace(s)
	s = strings.NewReplacer("\r\n", " ", "\n", " ", "\r", " ", "\t", " ").Replace(s)
	for strings.Contains(s, "  ") {
		s = strings.ReplaceAll(s, "  ", " ")
	}
	return s
}

// cleanBody trims a passage body. Gnokey and the gnoweb Actions form
// send newlines as the two characters `\n`, so they are turned back
// into real line breaks.
func cleanBody(s string) string {
	s = strings.ReplaceAll(s, `\n`, "\n")
	s = strings.ReplaceAll(s, "\r\n", "\n")
	return strings.TrimSpace(s)
}

func checkLen(s string, min, max int, err error) {
	if len(s) < min || len(s) > max {
		panic(err)
	}
}

// sameChoice compares two choice texts, ignoring case.
func sameChoice(a, b string) bool {
	return strings.ToLower(a) == strings.ToLower(b)
}

// canonPath walks from the opening of t along the most-cheered visible
// child at each step (ties go to the earliest passage) and returns the
// passages on the way. It is bounded by MaxDepth and MaxChoices.
func canonPath(t *Tale) []*Passage {
	root, ok := getPassage(t.Root)
	if !ok || root.Hidden {
		return nil
	}
	path := []*Passage{root}
	cur := root
	for !cur.Ending && len(path) <= MaxDepth {
		var best *Passage
		for _, cid := range cur.Children {
			c, ok := getPassage(cid)
			if !ok || c.Hidden {
				continue
			}
			if best == nil || c.Cheers > best.Cheers {
				best = c
			}
		}
		if best == nil {
			break
		}
		path = append(path, best)
		cur = best
	}
	return path
}

// ancestors returns the passages from the opening down to p, p included.
func ancestors(p *Passage) []*Passage {
	chain := make([]*Passage, p.Depth+1)
	for cur := p; cur != nil; {
		if cur.Depth < len(chain) {
			chain[cur.Depth] = cur
		}
		if cur.Parent == 0 {
			break
		}
		parent, ok := getPassage(cur.Parent)
		if !ok {
			break
		}
		cur = parent
	}
	return chain
}

func seqidOf(id int) seqid.ID {
	return seqid.ID(id)
}

package taletree

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	"gno.land/p/nt/ownable/v0"
	"gno.land/p/nt/seqid/v0"
)

// keeper moderates the whole realm: it can hide passages in any tale,
// lock any tale, and pause writing. It starts as the account that
// deployed the realm.
var keeper *ownable.Ownable

func init() {
	// init runs once, inside the addpkg transaction; there is no cur
	// here, so the deployer is read from the transaction origin.
	keeper = ownable.NewWithAddress(unsafe.OriginCaller())
}

// StartTale opens a new tale with its first passage and returns the
// tale id. The caller becomes the tale's narrator.
func StartTale(cur realm, title, opening string) int {
	assertNotPaused()
	caller := cur.Previous().Address()

	title = cleanLine(title)
	checkLen(title, MinTitleLen, MaxTitleLen, ErrTitleLength)
	opening = cleanBody(opening)
	checkLen(opening, MinBodyLen, MaxBodyLen, ErrBodyLength)

	now := time.Now()
	height := runtime.ChainHeight()
	tid := taleSeq.Next()
	pid := passageSeq.Next()

	passages.Set(pid.Binary(), &Passage{
		ID:        pid,
		Tale:      tid,
		Author:    caller,
		Body:      opening,
		Height:    height,
		CreatedAt: now,
	})
	tales.Set(tid.Binary(), &Tale{
		ID:        tid,
		Title:     title,
		Narrator:  caller,
		Root:      pid,
		Passages:  1,
		Height:    height,
		CreatedAt: now,
		UpdatedAt: now,
	})

	b := bardOf(caller)
	b.Passages++
	b.Tales++
	bardPassages.Set(bardPassageKey(caller, pid), pid)

	chain.Emit("TaleStarted",
		"tale", idStr(tid),
		"passage", idStr(pid),
		"narrator", caller.String(),
	)
	return int(tid)
}

// Branch writes a new passage under parentID. choice is the link text
// readers click to reach it ("Open the cellar door"); body is the
// passage itself. Returns the new passage id.
func Branch(cur realm, parentID int, choice, body string) int {
	return write(cur.Previous().Address(), parentID, choice, body, false)
}

// WriteEnding is Branch for a passage that ends its path: nobody can
// add choices under an ending.
func WriteEnding(cur realm, parentID int, choice, body string) int {
	return write(cur.Previous().Address(), parentID, choice, body, true)
}

func write(caller address, parentID int, choice, body string, ending bool) int {
	assertNotPaused()

	parent := mustGetVisiblePassage(parentID)
	t, _ := getTale(parent.Tale)
	if t.Locked {
		panic(ErrTaleLocked)
	}
	if parent.Ending {
		panic(ErrIsEnding)
	}
	if len(parent.Children) >= MaxChoices {
		panic(ErrTooManyChoices)
	}
	depth := parent.Depth + 1
	if depth > MaxDepth || (depth == MaxDepth && !ending) {
		panic(ErrTooDeep)
	}

	choice = cleanLine(choice)
	checkLen(choice, MinChoiceLen, MaxChoiceLen, ErrChoiceLength)
	body = cleanBody(body)
	checkLen(body, MinBodyLen, MaxBodyLen, ErrBodyLength)
	for _, sid := range parent.Children {
		if s, ok := getPassage(sid); ok && !s.Hidden && sameChoice(s.Choice, choice) {
			panic(ErrDuplicateChoice)
		}
	}

	now := time.Now()
	pid := passageSeq.Next()
	passages.Set(pid.Binary(), &Passage{
		ID:        pid,
		Tale:      t.ID,
		Parent:    parent.ID,
		Author:    caller,
		Choice:    choice,
		Body:      body,
		Depth:     depth,
		Ending:    ending,
		Height:    runtime.ChainHeight(),
		CreatedAt: now,
	})
	parent.Children = append(parent.Children, pid)

	t.Passages++
	if ending {
		t.Endings++
	}
	t.UpdatedAt = now

	bardOf(caller).Passages++
	bardPassages.Set(bardPassageKey(caller, pid), pid)

	chain.Emit("PassageWritten",
		"tale", idStr(t.ID),
		"passage", idStr(pid),
		"parent", idStr(parent.ID),
		"author", caller.String(),
		"ending", strconv.FormatBool(ending),
	)
	return int(pid)
}

// Cheer adds the caller's cheer to a passage. Each address can cheer a
// passage once, and not its own. Cheers pick the canon.
func Cheer(cur realm, passageID int) {
	caller := cur.Previous().Address()
	p := mustGetVisiblePassage(passageID)
	if p.Author == caller {
		panic(ErrSelfCheer)
	}
	key := p.ID.Binary() + caller.String()
	if cheers.Has(key) {
		panic(ErrAlreadyCheered)
	}
	cheers.Set(key, true)

	p.Cheers++
	t, _ := getTale(p.Tale)
	t.Cheers++
	author := bardOf(p.Author)
	setFame(author, author.Cheers+1)

	chain.Emit("Cheered",
		"passage", idStr(p.ID),
		"by", caller.String(),
		"cheers", strconv.Itoa(p.Cheers),
	)
}

// Tip forwards the ugnot sent with this call to the author of a
// passage, in full and in the same transaction:
//
//	gnokey maketx call -func Tip -args <passageID> -send 1000000ugnot ...
//
// Only a direct call from an account is accepted, so the coins checked
// below are the coins that reached this realm.
func Tip(cur realm, passageID int) {
	// Payment guard, kept as a pair (see effective-gno, "Verifying
	// inbound Coin payments"): IsUserCall ensures no realm or `maketx run`
	// script sat between the signer and this function, so OriginSend
	// is what this realm received.
	if !cur.Previous().IsUserCall() {
		panic(ErrTipCaller)
	}
	sent := unsafe.OriginSend()
	amount := sent.AmountOf("ugnot")
	if amount <= 0 || len(sent) != 1 {
		panic(ErrTipAmount)
	}

	caller := cur.Previous().Address()
	p := mustGetVisiblePassage(passageID)
	if p.Author == caller {
		panic(ErrSelfTip)
	}

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), p.Author, chain.NewCoins(chain.NewCoin("ugnot", amount)))

	p.Tips += amount
	bardOf(p.Author).Tips += amount
	totalTips += amount

	chain.Emit("Tipped",
		"passage", idStr(p.ID),
		"from", caller.String(),
		"to", p.Author.String(),
		"ugnot", strconv.FormatInt(amount, 10),
	)
}

// Hide takes a passage, and everything under it, off the pages. The
// text stays in state, so Unhide can bring it back. Allowed for the
// tale's narrator and the keeper.
func Hide(cur realm, passageID int, reason string) {
	caller := cur.Previous().Address()
	p := mustGetPassage(passageID)
	t, _ := getTale(p.Tale)
	assertModerator(caller, t)
	if p.Hidden {
		panic(ErrAlreadyHidden)
	}
	reason = cleanLine(reason)
	checkLen(reason, 0, MaxReasonLen, ErrReasonLength)

	p.Hidden = true
	p.HiddenReason = reason
	chain.Emit("PassageHidden", "passage", idStr(p.ID), "by", caller.String(), "reason", reason)
}

// Unhide reverses Hide.
func Unhide(cur realm, passageID int) {
	caller := cur.Previous().Address()
	p := mustGetPassage(passageID)
	t, _ := getTale(p.Tale)
	assertModerator(caller, t)
	if !p.Hidden {
		panic(ErrNotHidden)
	}
	p.Hidden = false
	p.HiddenReason = ""
	chain.Emit("PassageUnhidden", "passage", idStr(p.ID), "by", caller.String())
}

// LockTale closes a tale to new passages. Cheers and tips still work.
func LockTale(cur realm, taleID int) {
	caller := cur.Previous().Address()
	t := mustGetTale(taleID)
	assertModerator(caller, t)
	t.Locked = true
	chain.Emit("TaleLocked", "tale", idStr(t.ID), "by", caller.String())
}

// UnlockTale reopens a locked tale.
func UnlockTale(cur realm, taleID int) {
	caller := cur.Previous().Address()
	t := mustGetTale(taleID)
	assertModerator(caller, t)
	t.Locked = false
	chain.Emit("TaleUnlocked", "tale", idStr(t.ID), "by", caller.String())
}

// SetPaused stops (or resumes) all writing in the realm. Keeper only.
func SetPaused(cur realm, value bool) {
	keeper.AssertOwnedBy(cur.Previous().Address())
	paused = value
	chain.Emit("PauseChanged", "paused", strconv.FormatBool(value))
}

// TransferKeeper hands the keeper role to another address. Keeper only.
func TransferKeeper(cur realm, newKeeper address) {
	if err := keeper.TransferOwnership(0, cur, newKeeper); err != nil {
		panic(err)
	}
}

// Keeper returns the address of the realm keeper.
func Keeper() address {
	return keeper.Owner()
}

func assertNotPaused() {
	if paused {
		panic(ErrPaused)
	}
}

func assertModerator(caller address, t *Tale) {
	if caller != t.Narrator && !keeper.OwnedBy(caller) {
		panic(ErrUnauthorized)
	}
}

func idStr(id seqid.ID) string {
	return strconv.FormatUint(uint64(id), 10)
}

// Package erratabank records corrections, finder credit and book reward escrow.
package erratabank

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"unicode/utf8"

	"gno.land/p/g132vz03ycpaagtef4jmxjakstkppgyc5wn3r807/errata/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

const (
	Pending   = "Pending"
	Accepted  = "Accepted"
	Rejected  = "Rejected"
	Duplicate = "Duplicate"

	maxAmount    = 1<<63 - 1
	idKeyWidth   = 19
	maxListLimit = 50
)

type Book struct {
	ID               int
	Owner            address
	Title            string
	Edition          string
	Link             string
	RewardPerErratum int64
	OwnerFunds       int64
	SponsorFunds     int64
	Owed             int64
	Open             bool
	CreatedAt        int64
}

type Erratum struct {
	ID          int
	BookID      int
	Finder      address
	Location    string
	Text        string
	Status      string
	DuplicateOf int
	SubmittedAt int64
	ReviewedAt  int64
	Paid        int64
	Owed        int64
	Note        string
}

// Each book indexes all reports and each status by submission ID.
type bookRecord struct {
	book        Book
	all         avl.Tree
	pending     avl.Tree
	accepted    avl.Tree
	rejected    avl.Tree
	duplicate   avl.Tree
	byLocation  avl.Tree
	sponsors    avl.Tree
	owedReports avl.Tree
	nextOwedID  int
}

func (record *bookRecord) reports(status string) *avl.Tree {
	switch status {
	case "":
		return &record.all
	case Pending:
		return &record.pending
	case Accepted:
		return &record.accepted
	case Rejected:
		return &record.rejected
	case Duplicate:
		return &record.duplicate
	}
	return nil
}

type finderRecord struct {
	paid    int64
	owed    int64
	credits avl.Tree
	unpaid  avl.Tree
}

type FinderSummary struct {
	Credits       int
	UnpaidCredits int
	Paid          int64
	Owed          int64
}

var (
	books        = avl.NewTree()
	errataByID   = avl.NewTree()
	finders      = avl.NewTree()
	nextBookID   int
	nextReportID int
	realmURL     string
)

func init(cur realm) {
	realmURL = strings.TrimPrefix(cur.PkgPath(), "gno.land") + ":"
}

func idKey(id int) string {
	digits := strconv.Itoa(id)
	return strings.Repeat("0", idKeyWidth-len(digits)) + digits
}

func advanceID(counter *int) int {
	if *counter == maxAmount {
		panic(errIDLimit)
	}
	*counter += 1
	return *counter
}

func bookByID(id int) *bookRecord {
	if id <= 0 {
		return nil
	}
	book, _ := books.Get(idKey(id)).(*bookRecord)
	return book
}

func reportByID(id int) *Erratum {
	if id <= 0 {
		return nil
	}
	report, _ := errataByID.Get(idKey(id)).(*Erratum)
	return report
}

func requireBook(id int) *bookRecord {
	record := bookByID(id)
	if record == nil {
		panic(errBookMissing)
	}
	return record
}

func requireOwner(record *bookRecord, caller address) {
	if record.book.Owner != caller {
		panic(errOwnerOnly)
	}
}

func requireReview(id int, caller address) (*bookRecord, *Erratum) {
	report := reportByID(id)
	if report == nil {
		panic(errErratumMiss)
	}
	record := requireBook(report.BookID)
	requireOwner(record, caller)
	if report.Status != Pending {
		panic(errPendingOnly)
	}
	return record, report
}

func callerAddress(cur realm) address {
	if !cur.IsCurrent() {
		panic(errCurrentRealm)
	}
	return cur.Previous().Address()
}

// Gno v1.8.0 exposes the inbound coin envelope through unsafe.OriginSend.
// The Gno Security Guide requires IsUserCall before reading it.
// https://docs.gno.land/resources/gno-security-guide/#55-isuser-for-payment-guards
func inboundUgnot(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic(errDirectCall)
	}
	coins := unsafe.OriginSend()
	if len(coins) == 0 {
		return 0
	}
	if len(coins) != 1 || coins[0].Denom != "ugnot" {
		panic(errPaymentDenom)
	}
	if coins[0].Amount <= 0 {
		panic(errPayment)
	}
	return coins[0].Amount
}

func rejectCoins(cur realm) {
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) != 0 {
		panic(errRejectCoins)
	}
}

func addAmount(total, amount int64) int64 {
	if amount > maxAmount-total {
		panic(errOverflow)
	}
	return total + amount
}

func sendUgnot(cur realm, to address, amount int64) {
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

func requiredText(field, text string, max int) string {
	trimmed := strings.TrimSpace(text)
	if trimmed == "" || !utf8.ValidString(text) || utf8.RuneCountInString(text) > max {
		panic(field + " must contain 1 to " + strconv.Itoa(max) + " characters")
	}
	return trimmed
}

func reviewNote(note string) string {
	if strings.TrimSpace(note) == "" {
		return ""
	}
	return requiredText("review note", note, 300)
}

// CreateBook registers an open book and optionally credits inbound reward escrow.
func CreateBook(cur realm, title, edition, link string, rewardPerErratum int64) int {
	owner := callerAddress(cur)
	ownerFunds := inboundUgnot(cur)
	title = requiredText("title", title, 120)
	edition = requiredText("edition", edition, 120)
	link = requiredText("link", link, 300)
	if sanitize.URL(link) == "" {
		panic("unsupported book link")
	}
	if rewardPerErratum < 0 {
		panic("reward cannot be negative")
	}
	id := advanceID(&nextBookID)
	books.Set(idKey(id), &bookRecord{book: Book{
		ID: id, Owner: owner, Title: title, Edition: edition, Link: link,
		RewardPerErratum: rewardPerErratum, OwnerFunds: ownerFunds, Open: true, CreatedAt: runtime.ChainHeight(),
	}})
	chain.Emit("BookCreated", "book", strconv.Itoa(id), "owner", owner.String(),
		"reward", strconv.FormatInt(rewardPerErratum, 10), "owner_funds", strconv.FormatInt(ownerFunds, 10))
	return id
}

// Submit records a report. Reports are public and permanent on-chain.
func Submit(cur realm, bookID int, location, text string) int {
	finder := callerAddress(cur)
	rejectCoins(cur)
	record := requireBook(bookID)
	if !record.book.Open {
		panic(errClosed)
	}
	location = requiredText("location", location, 120)
	text = requiredText("text", text, 1000)
	id := advanceID(&nextReportID)
	key := idKey(id)
	errataByID.Set(key, &Erratum{
		ID: id, BookID: bookID, Finder: finder, Location: location, Text: text,
		Status: Pending, SubmittedAt: runtime.ChainHeight(),
	})
	record.all.Set(key, id)
	record.pending.Set(key, id)
	atLocation, _ := record.byLocation.Get(location).(*avl.Tree)
	if atLocation == nil {
		atLocation = avl.NewTree()
		record.byLocation.Set(location, atLocation)
	}
	atLocation.Set(key, id)
	chain.Emit("ErratumSubmitted", "book", strconv.Itoa(bookID), "erratum", strconv.Itoa(id),
		"finder", finder.String())
	return id
}

func review(record *bookRecord, report *Erratum, status, note string) {
	key := idKey(report.ID)
	record.pending.Remove(key)
	atLocation := record.byLocation.Get(report.Location).(*avl.Tree)
	atLocation.Remove(key)
	if atLocation.Size() == 0 {
		record.byLocation.Remove(report.Location)
	}
	record.reports(status).Set(key, report.ID)
	report.Status = status
	report.ReviewedAt = runtime.ChainHeight()
	report.Note = note
}

// Accept credits the finder and queues the reward for settlement from the book funds.
func Accept(cur realm, erratumID int, note string) {
	owner := callerAddress(cur)
	rejectCoins(cur)
	record, report := requireReview(erratumID, owner)
	if !record.book.Open {
		panic(errClosedAccept)
	}
	atLocation := record.byLocation.Get(report.Location).(*avl.Tree)
	_, first := atLocation.GetByIndex(0)
	if first.(int) != report.ID {
		panic(errEarlierPending)
	}
	review(record, report, Accepted, reviewNote(note))

	addr := report.Finder.String()
	finder, ok := finders.Get(addr).(*finderRecord)
	if !ok {
		finder = &finderRecord{}
		finders.Set(addr, finder)
	}
	key := idKey(erratumID)
	if reward := record.book.RewardPerErratum; reward > 0 && report.Finder != owner {
		finder.credits.Set(key, erratumID)
		record.queueReward(report, finder, reward)
		settleRewards(cur, record)
	} else {
		finder.unpaid.Set(key, erratumID)
	}
	chain.Emit("ErratumAccepted", "book", strconv.Itoa(report.BookID), "erratum", strconv.Itoa(erratumID),
		"finder", addr, "paid", strconv.FormatInt(report.Paid, 10), "owed", strconv.FormatInt(report.Owed, 10))
}

// Reject closes a pending submission without finder credit.
func Reject(cur realm, erratumID int, note string) {
	caller := callerAddress(cur)
	rejectCoins(cur)
	record, report := requireReview(erratumID, caller)
	review(record, report, Rejected, reviewNote(note))
	chain.Emit("ErratumRejected", "book", strconv.Itoa(report.BookID), "erratum", strconv.Itoa(erratumID))
}

// MarkDuplicate links a pending report to an earlier pending or accepted report in the same book.
func MarkDuplicate(cur realm, erratumID, originalID int) {
	caller := callerAddress(cur)
	rejectCoins(cur)
	record, report := requireReview(erratumID, caller)
	original := reportByID(originalID)
	if original == nil || original.BookID != report.BookID || original.ID >= report.ID ||
		(original.Status != Pending && original.Status != Accepted) {
		panic(errDuplicate)
	}
	report.DuplicateOf = originalID
	review(record, report, Duplicate, "")
	chain.Emit("ErratumMarkedDuplicate", "book", strconv.Itoa(report.BookID), "erratum", strconv.Itoa(erratumID),
		"original", strconv.Itoa(originalID))
}

// SetBookOpen controls submissions and acceptance. Closing opens sponsor refunds after debts settle.
func SetBookOpen(cur realm, bookID int, open bool) {
	caller := callerAddress(cur)
	rejectCoins(cur)
	record := requireBook(bookID)
	requireOwner(record, caller)
	if open && !record.book.Open && record.book.SponsorFunds > 0 {
		panic(errSponsorRefundsPending)
	}
	record.book.Open = open
	if !open {
		settleRewards(cur, record)
	}
	chain.Emit("BookOpenChanged", "book", strconv.Itoa(bookID), "open", strconv.FormatBool(open))
}

func GetBook(id int) (Book, bool) {
	if record := bookByID(id); record != nil {
		return record.book, true
	}
	return Book{}, false
}

func pageLimit(size, offset, limit int) int {
	if offset < 0 || limit <= 0 || offset >= size {
		return 0
	}
	if limit > maxListLimit {
		limit = maxListLimit
	}
	if remaining := size - offset; limit > remaining {
		limit = remaining
	}
	return limit
}

func ListBooks(offset, limit int) []Book {
	var result []Book
	if limit = pageLimit(books.Size(), offset, limit); limit == 0 {
		return result
	}
	books.IterateByOffset(offset, limit, func(_ string, value any) bool {
		result = append(result, value.(*bookRecord).book)
		return false
	})
	return result
}

func GetErratum(id int) (Erratum, bool) {
	if report := reportByID(id); report != nil {
		return *report, true
	}
	return Erratum{}, false
}

func listReports(tree *avl.Tree, offset, limit int) []Erratum {
	var result []Erratum
	if tree == nil {
		return result
	}
	if limit = pageLimit(tree.Size(), offset, limit); limit == 0 {
		return result
	}
	tree.IterateByOffset(offset, limit, func(_ string, value any) bool {
		report, _ := GetErratum(value.(int))
		result = append(result, report)
		return false
	})
	return result
}

// ListErrata returns reports in submission order. An empty status selects all reports.
func ListErrata(bookID int, status string, offset, limit int) []Erratum {
	if record := bookByID(bookID); record != nil {
		return listReports(record.reports(status), offset, limit)
	}
	return nil
}

func acceptedEntries(reports []Erratum) []errata.Entry {
	var entries []errata.Entry
	for _, report := range reports {
		entries = append(entries, errata.Entry{
			Location: report.Location, Text: report.Text, Finder: report.Finder.String(),
			FoundAt: report.SubmittedAt, Paid: report.Paid, Link: finderURL(report.Finder),
		})
	}
	return entries
}

// AcceptedEntries returns the first 50 accepted reports in submission order.
func AcceptedEntries(bookID int) []errata.Entry {
	return AcceptedEntriesPage(bookID, 0, maxListLimit)
}

// AcceptedEntriesPage is the integration API for rendering accepted reports.
// Limits are capped at 50 entries per page.
func AcceptedEntriesPage(bookID, offset, limit int) []errata.Entry {
	return acceptedEntries(ListErrata(bookID, Accepted, offset, limit))
}

func FinderStats(addr address) FinderSummary {
	if finder, ok := finders.Get(addr.String()).(*finderRecord); ok {
		return FinderSummary{
			Credits: finder.credits.Size(), UnpaidCredits: finder.unpaid.Size(),
			Paid: finder.paid, Owed: finder.owed,
		}
	}
	return FinderSummary{}
}

package erratabank

import (
	"chain"
	"strconv"
	"strings"
	"testing"

	"gno.land/p/nt/markdown/sanitize/v0"
)

const (
	testOwner   = address("g1dmt3sa5ucvecxuhf3j6ne5r0e3z4x7h6c03xc0")
	testReader  = address("g1akeqsvhucjt8gf5yupyzjxsjd29wv8fayng37c")
	testSponsor = address("g1juz2yxmdsa6audkp6ep9vfv80c8p5u76e03vvh")
	testLink    = "https://example.org/guide"
)

func assertPanic(t *testing.T, got any, want string) {
	t.Helper()
	if got != want {
		t.Fatalf("panic = %v, want %q", got, want)
	}
}

func TestReviewOrderAndPermissions(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(testOwner))
	book := CreateBook(cross(cur), "Review order", "First edition", testLink, 0)
	otherBook := CreateBook(cross(cur), "Other book", "First edition", testLink, 0)
	testing.SetRealm(testing.NewUserRealm(testReader))
	first := Submit(cross(cur), book, " Section 1 ", "The first correction.")
	other := Submit(cross(cur), otherBook, "Section 1", "This location is in another book.")
	testing.SetRealm(testing.NewUserRealm(testSponsor))
	later := Submit(cross(cur), book, "Section 1", "The second correction.")
	assertPanic(t, revive(func() { Accept(cross(cur), first, "") }), errOwnerOnly)
	assertPanic(t, revive(func() { Reject(cross(cur), first, "") }), errOwnerOnly)
	assertPanic(t, revive(func() { MarkDuplicate(cross(cur), later, first) }), errOwnerOnly)
	assertPanic(t, revive(func() { Withdraw(cross(cur), book, 1) }), errOwnerOnly)

	testing.SetRealm(testing.NewUserRealm(testOwner))
	assertPanic(t, revive(func() { Accept(cross(cur), later, "") }), errEarlierPending)
	assertPanic(t, revive(func() { MarkDuplicate(cross(cur), first, later) }), errDuplicate)
	assertPanic(t, revive(func() { MarkDuplicate(cross(cur), later, other) }), errDuplicate)
	Accept(cross(cur), other, "")
	Accept(cross(cur), first, "")
	MarkDuplicate(cross(cur), later, first)
	duplicate, _ := GetErratum(later)
	if duplicate.Status != Duplicate || duplicate.DuplicateOf != first {
		t.Fatalf("wrong duplicate record: %+v", duplicate)
	}

	testing.SetRealm(testing.NewUserRealm(testReader))
	original := Submit(cross(cur), book, "Alternate section", "Report before Section 2.")
	firstAtLocation := Submit(cross(cur), book, "Section 2", "First at this location.")
	secondAtLocation := Submit(cross(cur), book, "Section 2", "Second at this location.")
	rejected := Submit(cross(cur), book, "Section 3", "Unconfirmed report.")
	confirmed := Submit(cross(cur), book, "Section 3", "Confirmed report.")
	testing.SetRealm(testing.NewUserRealm(testOwner))
	MarkDuplicate(cross(cur), firstAtLocation, original)
	Accept(cross(cur), secondAtLocation, "")
	Reject(cross(cur), rejected, "")
	assertPanic(t, revive(func() { MarkDuplicate(cross(cur), confirmed, rejected) }), errDuplicate)
	Accept(cross(cur), confirmed, "")
	pending, _ := GetErratum(original)
	if pending.Status != Pending {
		t.Fatalf("marking a duplicate changed the original status: %s", pending.Status)
	}
	assertPanic(t, revive(func() { Accept(cross(cur), first, "") }), errPendingOnly)
}

func TestFinderReputationAndOwed(cur realm, t *testing.T) {
	author := chain.PackageAddress("gno.land/r/test/reputationauthor")
	finder := chain.PackageAddress("gno.land/r/test/reputationfinder")
	testing.SetRealm(testing.NewUserRealm(author))
	rewarded := CreateBook(cross(cur), "Rewarded book", "First edition", testLink, 1000)
	creditOnly := CreateBook(cross(cur), "Credit-only book", "First edition", testLink, 0)
	self := Submit(cross(cur), rewarded, "Owner note", "A maintainer's own correction.")
	testing.SetRealm(testing.NewUserRealm(finder))
	eligible := Submit(cross(cur), rewarded, "Rewarded location", "A reader's correction.")
	unpaid := Submit(cross(cur), creditOnly, "Volunteer note", "A voluntary correction.")
	testing.SetRealm(testing.NewUserRealm(author))
	Accept(cross(cur), self, "")
	Accept(cross(cur), eligible, "")
	Accept(cross(cur), unpaid, "")

	owner := FinderStats(author)
	if owner.Credits != 0 || owner.UnpaidCredits != 1 || owner.Paid != 0 || owner.Owed != 0 {
		t.Fatalf("self-owned correction counted as a reward: %+v", owner)
	}
	reader := FinderStats(finder)
	if reader.Credits != 1 || reader.UnpaidCredits != 1 || reader.Paid != 0 || reader.Owed != 1000 {
		t.Fatalf("wrong reader reputation or reward ledger: %+v", reader)
	}
	path := "finder/" + finder.String()
	main := Render(path)
	if !strings.Contains(main, "Reward-eligible credits: 1") ||
		!strings.Contains(main, "Owed: 0.001 GNOT") ||
		!strings.Contains(main, "Paid: 0 GNOT") ||
		!strings.Contains(main, "Rewarded location") || strings.Contains(main, "Volunteer note") {
		t.Fatalf("wrong finder view: %s", main)
	}
	unpaidPage := Render(path + "/unpaid")
	if !strings.Contains(unpaidPage, "## Unpaid credits") ||
		!strings.Contains(unpaidPage, "Volunteer note") || strings.Contains(unpaidPage, "Rewarded location") {
		t.Fatalf("wrong unpaid page: %s", unpaidPage)
	}
}

func TestFundingAndClosureGuards(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(testOwner))
	book := CreateBook(cross(cur), "Funding guards", "First edition", testLink, 1000)
	assertPanic(t, revive(func() { FundBook(cross(cur), book) }), errPayment)
	testing.SetOriginSend(chain.Coins{{Denom: "utest", Amount: 100}})
	assertPanic(t, revive(func() { FundBook(cross(cur), book) }), errPaymentDenom)
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 500)))
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/test/fundingcaller"))
	assertPanic(t, revive(func() { FundBook(cross(cur), book) }), errDirectCall)

	testing.SetRealm(testing.NewUserRealm(testSponsor))
	FundBook(cross(cur), book)
	assertPanic(t, revive(func() { RefundSponsor(cross(cur), book) }), errRejectCoins)
	testing.SetOriginSend(nil)
	assertPanic(t, revive(func() { RefundSponsor(cross(cur), book) }), errRefundUnavailable)
	report := Submit(cross(cur), book, "Section 1", "A sponsored report.")
	testing.SetRealm(testing.NewUserRealm(testOwner))
	assertPanic(t, revive(func() { Withdraw(cross(cur), book, 1) }), errWithdraw)
	SetBookOpen(cross(cur), book, false)
	assertPanic(t, revive(func() { Accept(cross(cur), report, "") }), errClosedAccept)
	assertPanic(t, revive(func() { SetBookOpen(cross(cur), book, true) }), errSponsorRefundsPending)
	assertPanic(t, revive(func() { RefundSponsor(cross(cur), book) }), errNoSponsorFunds)

	testing.SetRealm(testing.NewUserRealm(testReader))
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 1)))
	assertPanic(t, revive(func() { FundBook(cross(cur), book) }), errClosedSponsor)
	assertPanic(t, revive(func() { SettleOwed(cross(cur), book) }), errRejectCoins)
	testing.SetOriginSend(nil)
	if SponsorBalance(book, testSponsor) != 500 {
		t.Fatal("a blocked action changed the sponsor balance")
	}
}

