func renderPending(w *mux.ResponseWriter, req *mux.Request) {
	renderReportList(w, req, Pending, "Pending reports", "/pending")
}

func renderAll(w *mux.ResponseWriter, req *mux.Request) {
	renderReportList(w, req, "", "All reports", "/all")
}

func renderReportList(w *mux.ResponseWriter, req *mux.Request, status, heading, suffix string) {
	record := routeBook(w, req)
	if record == nil {
		return
	}
	tree := record.reports(status)
	offset, ok := pageOffset(req, tree.Size())
	if !ok {
		notFound(w, "Page")
		return
	}
	book := record.book
	w.Write(ufmt.Sprintf("# %s\n\n[Back to %s](%s)\n\n",
		heading, sanitize.InlineText(book.Title), bookURL(book.ID)))
	if tree.Size() == 0 {
		w.Write("No reports here yet.\n")
		return
	}
	header := "| Report | Location | Status | Finder | Height found |"
	dividers := "| --- | --- | --- | --- | ---: |"
	if status == "" {
		header += " Correction |"
		dividers += " --- |"
	}
	w.Write(header + "\n" + dividers + "\n")
	for _, report := range listReports(tree, offset, pageSize) {
		w.Write(ufmt.Sprintf("| [#%d](%s) | %s | %s | [%s](%s) | %d |",
			report.ID, erratumURL(report.ID), sanitize.TableCell(report.Location), report.Status,
			errata.ShortAddr(report.Finder.String()), finderURL(report.Finder), report.SubmittedAt))
		if status == "" {
			w.Write(" " + sanitize.TableCell(report.Text))
			if report.Status == Rejected && report.Note != "" {
				w.Write(" — " + sanitize.TableCell(report.Note))
			}
			w.Write(" |")
		}
		w.Write("\n")
	}
	pagination(w, bookRoute(book.ID)+suffix, offset, tree.Size())
}

func renderErratum(w *mux.ResponseWriter, req *mux.Request) {
	id, err := strconv.Atoi(req.GetVar("id"))
	report, ok := GetErratum(id)
	if err != nil || !ok {
		notFound(w, "Erratum")
		return
	}
	book, _ := GetBook(report.BookID)
	w.Write(ufmt.Sprintf("# Erratum #%d\n\n[Back to %s](%s)\n\n",
		id, sanitize.InlineText(book.Title), bookURL(book.ID)))
	w.Write(ufmt.Sprintf("- Location: %s\n- Finder: [%s](%s)\n- Status: %s\n- Paid: %s\n- Owed: %s\n\n",
		sanitize.InlineText(report.Location), report.Finder.String(), finderURL(report.Finder),
		report.Status, errata.FormatUgnot(report.Paid), errata.FormatUgnot(report.Owed)))
	if report.Status == Rejected {
		w.Write("[View the rejected correction in All reports](" + bookURL(book.ID) + "/all)\n\n")
	} else {
		w.Write("## Correction\n\n" + sanitize.InlineText(report.Text) + "\n\n")
	}
	w.Write(ufmt.Sprintf("## Status history\n\n- Height %d — Pending (submitted)\n", report.SubmittedAt))
	if report.Status != Pending {
		w.Write(ufmt.Sprintf("- Height %d — %s\n", report.ReviewedAt, report.Status))
	}
	if report.Note != "" && report.Status != Rejected {
		w.Write("- Review note: " + sanitize.InlineText(report.Note) + "\n")
	}
	if report.DuplicateOf != 0 {
		w.Write(ufmt.Sprintf("- Earlier report: [#%d](%s)\n", report.DuplicateOf, erratumURL(report.DuplicateOf)))
	}
}

func renderFinder(w *mux.ResponseWriter, req *mux.Request) {
	renderFinderCredits(w, req, false)
}

func renderUnpaidFinder(w *mux.ResponseWriter, req *mux.Request) {
	renderFinderCredits(w, req, true)
}

func renderFinderCredits(w *mux.ResponseWriter, req *mux.Request, unpaid bool) {
	raw := req.GetVar("addr")
	cleaned := sanitize.BechString(raw, "g")
	if cleaned == "" || cleaned != raw || !address(cleaned).IsValid() {
		notFound(w, "Finder")
		return
	}
	addr := address(cleaned)
	stats := FinderStats(addr)
	finder, _ := finders.Get(cleaned).(*finderRecord)
	route := "finder/" + cleaned
	count := stats.Credits
	var tree *avl.Tree
	if finder != nil {
		tree = &finder.credits
	}
	if unpaid {
		route += "/unpaid"
		count = stats.UnpaidCredits
		if finder != nil {
			tree = &finder.unpaid
		}
	}
	offset, ok := pageOffset(req, count)
	if !ok {
		notFound(w, "Page")
		return
	}

	w.Write(ufmt.Sprintf("# Finder account\n\n%s\n\n- Reward-eligible credits: %d\n- Unpaid credits: %d\n- Paid: %s\n- Owed: %s\n\n",
		sanitize.InlineCode(cleaned), stats.Credits, stats.UnpaidCredits,
		errata.FormatUgnot(stats.Paid), errata.FormatUgnot(stats.Owed)))
	if unpaid {
		w.Write("[Reward-eligible credits](" + finderURL(addr) + ")\n\n## Unpaid credits\n\n")
	} else {
		w.Write("[Unpaid credits](" + finderURL(addr) + "/unpaid)\n\n## Reward-eligible credits\n\n")
	}
	if count == 0 {
		w.Write("No credits in this view yet.\n")
		return
	}
	w.Write("| Book | Find | Height found | Paid | Owed |\n| --- | --- | ---: | ---: | ---: |\n")
	for _, report := range listReports(tree, offset, pageSize) {
		book, _ := GetBook(report.BookID)
		w.Write(ufmt.Sprintf("| [%s](%s) | [%s](%s) | %d | %s | %s |\n",
			sanitize.TableCell(book.Title), bookURL(book.ID),
			sanitize.TableCell(report.Location), erratumURL(report.ID), report.SubmittedAt,
			errata.FormatUgnot(report.Paid), errata.FormatUgnot(report.Owed)))
	}
	pagination(w, route, offset, count)
}

// Package quorummath provides pure, deterministic escrow split math,
// quorum validation, and gnoweb formatting utilities for BountyQuorum.
package quorummath

import (
	"strconv"
	"strings"
)

const (
	// MaxBps represents 100.00% in basis points.
	MaxBps = 10000
	// UgnotPerGnot is the number of micro-GNOT in 1 GNOT.
	UgnotPerGnot = 1000000
)

// ValidateQuorum ensures quorum is strictly positive and does not exceed reviewerCount.
func ValidateQuorum(reviewerCount, quorum int) string {
	if reviewerCount <= 0 {
		return "at least one reviewer is required"
	}
	if quorum <= 0 {
		return "quorum must be at least 1"
	}
	if quorum > reviewerCount {
		return "quorum cannot exceed reviewer count"
	}
	return ""
}

// ParseCSVAddresses parses a comma-separated list of unique Gno addresses.
// Returns deduplicated addresses and an error message (empty if valid).
func ParseCSVAddresses(raw string) ([]address, string) {
	parts := strings.Split(raw, ",")
	seen := make(map[string]bool)
	out := make([]address, 0, len(parts))

	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed == "" {
			continue
		}
		a := address(trimmed)
		if !a.IsValid() {
			return nil, "invalid reviewer address: " + trimmed
		}
		key := a.String()
		if seen[key] {
			return nil, "duplicate reviewer address: " + key
		}
		seen[key] = true
		out = append(out, a)
	}
	if len(out) == 0 {
		return nil, "reviewer list cannot be empty"
	}
	return out, ""
}

// ComputeMilestonePayout computes the ugnot payout for a milestone with weightBps
// out of totalEscrow. If isLastFullAllocation is true (total allocated bps == 10000
// and this is the last unpaid milestone), it returns remainingEscrow to prevent
// integer-division dust from ever being locked in the contract.
func ComputeMilestonePayout(totalEscrow, remainingEscrow int64, weightBps int, isFinalRemainder bool) int64 {
	if remainingEscrow <= 0 || totalEscrow <= 0 || weightBps <= 0 {
		return 0
	}
	if isFinalRemainder {
		return remainingEscrow
	}
	payout := (totalEscrow * int64(weightBps)) / int64(MaxBps)
	if payout > remainingEscrow {
		return remainingEscrow
	}
	return payout
}

// QuorumOutcome determines the voting state given reviewerCount, quorum, approvals, and rejections.
// Returns "approved", "rejected", or "pending".
func QuorumOutcome(reviewerCount, quorum, approvals, rejections int) string {
	if approvals >= quorum {
		return "approved"
	}
	remaining := reviewerCount - approvals - rejections
	if approvals+remaining < quorum {
		return "rejected"
	}
	return "pending"
}

// FormatUGNOT renders a ugnot amount as human-readable GNOT plus raw ugnot.
func FormatUGNOT(amount int64) string {
	if amount < 0 {
		return "-" + FormatUGNOT(-amount)
	}
	whole := amount / UgnotPerGnot
	frac := amount % UgnotPerGnot
	fracStr := strconv.FormatInt(frac, 10)
	for len(fracStr) < 6 {
		fracStr = "0" + fracStr
	}
	// Trim trailing zeros down to at least 2 decimals for clean tables.
	for len(fracStr) > 2 && fracStr[len(fracStr)-1] == '0' {
		fracStr = fracStr[:len(fracStr)-1]
	}
	return strconv.FormatInt(whole, 10) + "." + fracStr + " GNOT"
}

// ProgressBar renders a fixed-width text progress bar for gnoweb Markdown tables.
func ProgressBar(paidBps, width int) string {
	if width <= 0 {
		width = 10
	}
	if paidBps < 0 {
		paidBps = 0
	}
	if paidBps > MaxBps {
		paidBps = MaxBps
	}
	filled := (paidBps * width) / MaxBps
	var sb strings.Builder
	sb.WriteString("[")
	for i := 0; i < width; i++ {
		if i < filled {
			sb.WriteString("#")
		} else {
			sb.WriteString("-")
		}
	}
	pct := paidBps / 100
	sb.WriteString("] ")
	sb.WriteString(strconv.Itoa(pct))
	sb.WriteString("%")
	return sb.String()
}

// ShortAddr formats a Gno address compactly for tables (e.g. g1yf6p...e5qd).
func ShortAddr(a address) string {
	s := a.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "..." + s[len(s)-4:]
}

package quorummath

import (
	"chain"
	"testing"
)

func TestValidateQuorum(t *testing.T) {
	if msg := ValidateQuorum(3, 2); msg != "" {
		t.Fatalf("expected valid quorum, got %s", msg)
	}
	if msg := ValidateQuorum(1, 1); msg != "" {
		t.Fatalf("expected valid 1-of-1 quorum, got %s", msg)
	}
	if ValidateQuorum(0, 1) == "" {
		t.Fatal("expected error for 0 reviewers")
	}
	if ValidateQuorum(3, 0) == "" {
		t.Fatal("expected error for 0 quorum")
	}
	if ValidateQuorum(2, 3) == "" {
		t.Fatal("expected error for quorum > reviewers")
	}
}

func TestParseCSVAddresses(t *testing.T) {
	a1 := chain.PackageAddress("gno.land/r/test/rev1")
	a2 := chain.PackageAddress("gno.land/r/test/rev2")

	addrs, errMsg := ParseCSVAddresses(a1.String() + ", " + a2.String())
	if errMsg != "" {
		t.Fatalf("unexpected error: %s", errMsg)
	}
	if len(addrs) != 2 || addrs[0] != a1 || addrs[1] != a2 {
		t.Fatalf("unexpected parsed addrs: %v", addrs)
	}

	if _, errMsg = ParseCSVAddresses(a1.String() + "," + a1.String()); errMsg == "" {
		t.Fatal("expected duplicate address error")
	}
	if _, errMsg = ParseCSVAddresses("not_a_valid_addr"); errMsg == "" {
		t.Fatal("expected invalid address error")
	}
	if _, errMsg = ParseCSVAddresses(" , "); errMsg == "" {
		t.Fatal("expected empty list error")
	}
}

func TestComputeMilestonePayout_ZeroDust(t *testing.T) {
	total := int64(1000)
	p1 := ComputeMilestonePayout(total, total, 3333, false)
	rem := total - p1
	p2 := ComputeMilestonePayout(total, rem, 3333, false)
	rem -= p2
	p3 := ComputeMilestonePayout(total, rem, 3334, true)

	if p1 != 333 || p2 != 333 || p3 != 334 || p1+p2+p3 != total {
		t.Fatalf("dust mismatch: p1=%d p2=%d p3=%d sum=%d", p1, p2, p3, p1+p2+p3)
	}
}

func TestQuorumOutcome(t *testing.T) {
	cases := []struct {
		n, q, a, r int
		want       string
	}{
		{3, 2, 1, 0, "pending"},
		{3, 2, 1, 1, "pending"},
		{3, 2, 2, 0, "approved"},
		{3, 2, 2, 1, "approved"},
		{3, 2, 0, 2, "rejected"},
		{3, 2, 1, 2, "rejected"},
	}
	for _, tc := range cases {
		if got := QuorumOutcome(tc.n, tc.q, tc.a, tc.r); got != tc.want {
			t.Fatalf("QuorumOutcome(%d,%d,%d,%d)=%s want %s", tc.n, tc.q, tc.a, tc.r, got, tc.want)
		}
	}
}

func TestFormatUGNOTAndProgressBar(t *testing.T) {
	if got := FormatUGNOT(1500000); got != "1.50 GNOT" {
		t.Fatalf("got %s", got)
	}
	if got := FormatUGNOT(1); got != "0.000001 GNOT" {
		t.Fatalf("got %s", got)
	}
	if got := FormatUGNOT(10000000); got != "10.00 GNOT" {
		t.Fatalf("got %s", got)
	}
	if got := ProgressBar(5000, 10); got != "[#####-----] 50%" {
		t.Fatalf("got %s", got)
	}
	if got := ProgressBar(10000, 10); got != "[##########] 100%" {
		t.Fatalf("got %s", got)
	}
}

// Package bountyquorum implements an on-chain milestone escrow and
// quorum-verified bounty board for DAOs, grants, and agent/builder quests.
//
// Security design:
//   - All ugnot funding entry points require a direct EOA user call
//     (cur.Previous().IsUserCall()) before reading unsafe.OriginSend(),
//     eliminating phantom OriginSend draining via intermediary realms.
//   - Milestone weights are denominated in basis points (sum <= 10000).
//     The final milestone covering 100% receives exact remainingEscrow,
//     guaranteeing zero integer-division dust is ever stranded.
//   - Double-voting is prevented per (milestone, submissionRound, reviewer).
//   - Rejected milestones cleanly reset into an iterative resubmission cycle.
//   - Sponsors can safely reclaim unspent escrow only after the deadline,
//     or cancel before any milestone has been paid out.
package bountyquorum

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1yf6p3wr7lame69dqx6savrskkpu7qgalsxe5qd/quorummath"
)

const (
	// StatusOpen means the quest is actively accepting submissions and reviews.
	StatusOpen = "OPEN"
	// StatusCompleted means all escrow has been paid out to builders.
	StatusCompleted = "COMPLETED"
	// StatusReclaimed means unspent escrow was reclaimed after expiry.
	StatusReclaimed = "RECLAIMED"
	// StatusCancelled means the quest was cancelled before any payout.
	StatusCancelled = "CANCELLED"

	// MilestonePending means no submission is awaiting review yet.
	MilestonePending = "PENDING"
	// MilestoneSubmitted means a builder deliverable is currently under quorum review.
	MilestoneSubmitted = "SUBMITTED"
	// MilestoneRejected means reviewers could no longer reach quorum; open for resubmission.
	MilestoneRejected = "REJECTED"
	// MilestonePaid means approval quorum was reached and ugnot was transferred to the builder.
	MilestonePaid = "PAID"
)

// ReviewRecord logs an individual reviewer's vote on a milestone submission round.
type ReviewRecord struct {
	Round    int
	Reviewer address
	Approve  bool
	Comment  string
	At       time.Time
}

// Milestone represents a single weighted deliverable within a Quest.
type Milestone struct {
	Label          string
	WeightBps      int
	Status         string
	Round          int
	Builder        address
	DeliverableURL string
	ProofHash      string
	Notes          string
	Approvals      int
	Rejections     int
	PaidAmount     int64
	PaidAt         time.Time
	VotedInRound   map[string]bool // "<round>:<reviewer>" -> voted
	History        []*ReviewRecord
}

// Quest represents an escrowed bounty with multiple milestones and a reviewer quorum.
type Quest struct {
	ID              int
	Title           string
	Summary         string
	Sponsor         address
	Reviewers       []address
	ReviewerSet     map[string]bool
	Quorum          int
	TotalEscrow     int64
	RemainingEscrow int64
	PaidOut         int64
	AllocatedBps    int
	PaidBps         int
	Status          string
	CreatedAt       time.Time
	Deadline        time.Time
	Milestones      []*Milestone
}

// BuilderStats tracks cumulative verified earnings per builder address.
type BuilderStats struct {
	Builder         address
	TotalEarned     int64
	MilestonesWon   int
	CompletedQuests []string // "Q#<id> M#<idx>"
}

var (
	quests          []*Quest
	questByID       map[int]*Quest
	builderStatsMap map[string]*BuilderStats
	builderList     []*BuilderStats
	nextQuestID     int
	totalEscrowed   int64
	totalDisbursed  int64
)

func init() {
	resetState()
}

func resetState() {
	quests = make([]*Quest, 0)
	questByID = make(map[int]*Quest)
	builderStatsMap = make(map[string]*BuilderStats)
	builderList = make([]*BuilderStats, 0)
	nextQuestID = 1
	totalEscrowed = 0
	totalDisbursed = 0
}

func mustUserCall(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("only direct user calls (maketx call) are accepted")
	}
	return cur.Previous().Address()
}

func mustOriginUGNOT() int64 {
	sent := unsafe.OriginSend()
	if len(sent) == 0 {
		panic("must send ugnot to fund escrow")
	}
	amount := sent.AmountOf("ugnot")
	if amount <= 0 || len(sent) != 1 {
		panic("escrow accepts strictly positive ugnot only")
	}
	return amount
}

func sendEscrowUGNOT(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.Coins{{Denom: "ugnot", Amount: amount}})
}

func mustGetQuest(questID int) *Quest {
	q, ok := questByID[questID]
	if !ok {
		panic("quest not found: " + strconv.Itoa(questID))
	}
	return q
}

// CreateQuest locks sent ugnot in escrow and creates a new quorum-verified bounty quest.
// Returns the new quest ID.
func CreateQuest(
	cur realm,
	title string,
	summary string,
	reviewersCSV string,
	quorum int,
	durationHours int64,
) int {
	sponsor := mustUserCall(cur)
	amount := mustOriginUGNOT()

	title = strings.TrimSpace(title)
	summary = strings.TrimSpace(summary)
	if title == "" {
		panic("quest title cannot be empty")
	}
	if durationHours <= 0 {
		panic("durationHours must be positive")
	}

	reviewers, errMsg := quorummath.ParseCSVAddresses(reviewersCSV)
	if errMsg != "" {
		panic(errMsg)
	}
	if qErr := quorummath.ValidateQuorum(len(reviewers), quorum); qErr != "" {
		panic(qErr)
	}

	revSet := make(map[string]bool)
	for _, r := range reviewers {
		revSet[r.String()] = true
	}

	now := time.Now()
	id := nextQuestID
	nextQuestID++

	q := &Quest{
		ID:              id,
		Title:           title,
		Summary:         summary,
		Sponsor:         sponsor,
		Reviewers:       reviewers,
		ReviewerSet:     revSet,
		Quorum:          quorum,
		TotalEscrow:     amount,
		RemainingEscrow: amount,
		Status:          StatusOpen,
		CreatedAt:       now,
		Deadline:        now.Add(time.Duration(durationHours) * time.Hour),
		Milestones:      make([]*Milestone, 0),
	}

	quests = append(quests, q)
	questByID[id] = q
	totalEscrowed += amount

	chain.Emit(
		"QuestCreated",
		"quest_id", strconv.Itoa(id),
		"sponsor", sponsor.String(),
		"escrow_ugnot", strconv.FormatInt(amount, 10),
		"quorum", strconv.Itoa(quorum),
	)
	return id
}

// TopUpQuest lets any sponsor or community contributor add more ugnot into an open quest.
func TopUpQuest(cur realm, questID int) {
	contributor := mustUserCall(cur)
	amount := mustOriginUGNOT()

	q := mustGetQuest(questID)
	if q.Status != StatusOpen {
		panic("can only top up an open quest")
	}
	if time.Now().After(q.Deadline) {
		panic("quest deadline has already passed")
	}

	q.TotalEscrow += amount
	q.RemainingEscrow += amount
	totalEscrowed += amount

	chain.Emit(
		"QuestToppedUp",
		"quest_id", strconv.Itoa(questID),
		"contributor", contributor.String(),
		"added_ugnot", strconv.FormatInt(amount, 10),
	)
}

// AddMilestone defines a weighted deliverable milestone for an open quest.
// Only the quest sponsor can add milestones, and total weights cannot exceed 10000 bps (100%).
func AddMilestone(cur realm, questID int, label string, weightBps int) int {
	caller := cur.Previous().Address()
	q := mustGetQuest(questID)

	if caller != q.Sponsor {
		panic("only the quest sponsor can add milestones")
	}
	if q.Status != StatusOpen {
		panic("quest is not open")
	}
	label = strings.TrimSpace(label)
	if label == "" {
		panic("milestone label cannot be empty")
	}
	if weightBps <= 0 || q.AllocatedBps+weightBps > quorummath.MaxBps {
		panic("milestone weightBps invalid or exceeds 10000 bps total")
	}

	m := &Milestone{
		Label:        label,
		WeightBps:    weightBps,
		Status:       MilestonePending,
		VotedInRound: make(map[string]bool),
		History:      make([]*ReviewRecord, 0),
	}
	q.Milestones = append(q.Milestones, m)
	q.AllocatedBps += weightBps

	idx := len(q.Milestones) - 1
	chain.Emit(
		"MilestoneAdded",
		"quest_id", strconv.Itoa(questID),
		"milestone_idx", strconv.Itoa(idx),
		"weight_bps", strconv.Itoa(weightBps),
	)
	return idx
}

// SubmitDeliverable submits (or resubmits after rejection) a builder's proof of work for a milestone.
func SubmitDeliverable(
	cur realm,
	questID int,
	milestoneIdx int,
	deliverableURL string,
	proofHash string,
	notes string,
) {
	builder := cur.Previous().Address()
	q := mustGetQuest(questID)

	if q.Status != StatusOpen {
		panic("quest is not open")
	}
	if time.Now().After(q.Deadline) {
		panic("quest deadline has passed")
	}
	if milestoneIdx < 0 || milestoneIdx >= len(q.Milestones) {
		panic("milestone index out of range")
	}

	m := q.Milestones[milestoneIdx]
	if m.Status == MilestonePaid {
		panic("milestone is already paid")
	}
	if m.Status == MilestoneSubmitted {
		panic("milestone already has a submission under active review")
	}

	deliverableURL = strings.TrimSpace(deliverableURL)
	if deliverableURL == "" {
		panic("deliverableURL cannot be empty")
	}

	m.Round++
	m.Builder = builder
	m.DeliverableURL = deliverableURL
	m.ProofHash = strings.TrimSpace(proofHash)
	m.Notes = strings.TrimSpace(notes)
	m.Approvals = 0
	m.Rejections = 0
	m.Status = MilestoneSubmitted

	chain.Emit(
		"DeliverableSubmitted",
		"quest_id", strconv.Itoa(questID),
		"milestone_idx", strconv.Itoa(milestoneIdx),
		"round", strconv.Itoa(m.Round),
		"builder", builder.String(),
	)
}

// ReviewMilestone records a designated reviewer's approve/reject vote for the current submission round.
// Automatically releases escrowed ugnot to the builder the moment approval quorum is reached.
func ReviewMilestone(
	cur realm,
	questID int,
	milestoneIdx int,
	approve bool,
	comment string,
) string {
	reviewer := cur.Previous().Address()
	q := mustGetQuest(questID)

	if q.Status != StatusOpen {
		panic("quest is not open")
	}
	if !q.ReviewerSet[reviewer.String()] {
		panic("caller is not a designated reviewer for this quest")
	}
	if milestoneIdx < 0 || milestoneIdx >= len(q.Milestones) {
		panic("milestone index out of range")
	}

	m := q.Milestones[milestoneIdx]
	if m.Status != MilestoneSubmitted {
		panic("milestone is not awaiting review")
	}
	if reviewer == m.Builder {
		panic("builder cannot review their own deliverable")
	}

	voteKey := strconv.Itoa(m.Round) + ":" + reviewer.String()
	if m.VotedInRound[voteKey] {
		panic("reviewer has already voted in this submission round")
	}
	m.VotedInRound[voteKey] = true

	if approve {
		m.Approvals++
	} else {
		m.Rejections++
	}

	m.History = append(m.History, &ReviewRecord{
		Round:    m.Round,
		Reviewer: reviewer,
		Approve:  approve,
		Comment:  strings.TrimSpace(comment),
		At:       time.Now(),
	})

	outcome := quorummath.QuorumOutcome(len(q.Reviewers), q.Quorum, m.Approvals, m.Rejections)
	if outcome == "approved" {
		isFinalFull := (q.AllocatedBps == quorummath.MaxBps) && (q.PaidBps+m.WeightBps == quorummath.MaxBps)
		payout := quorummath.ComputeMilestonePayout(q.TotalEscrow, q.RemainingEscrow, m.WeightBps, isFinalFull)

		m.Status = MilestonePaid
		m.PaidAmount = payout
		m.PaidAt = time.Now()

		q.RemainingEscrow -= payout
		q.PaidOut += payout
		q.PaidBps += m.WeightBps
		totalDisbursed += payout

		if q.RemainingEscrow == 0 || q.PaidBps >= quorummath.MaxBps {
			q.Status = StatusCompleted
		}

		recordBuilderWin(m.Builder, payout, q.ID, milestoneIdx)
		sendEscrowUGNOT(cur, m.Builder, payout)

		chain.Emit(
			"MilestonePaid",
			"quest_id", strconv.Itoa(questID),
			"milestone_idx", strconv.Itoa(milestoneIdx),
			"builder", m.Builder.String(),
			"payout_ugnot", strconv.FormatInt(payout, 10),
		)
	} else if outcome == "rejected" {
		m.Status = MilestoneRejected
		chain.Emit(
			"MilestoneRejected",
			"quest_id", strconv.Itoa(questID),
			"milestone_idx", strconv.Itoa(milestoneIdx),
			"round", strconv.Itoa(m.Round),
		)
	}
	return outcome
}

func recordBuilderWin(builder address, payout int64, questID, milestoneIdx int) {
	key := builder.String()
	st, ok := builderStatsMap[key]
	if !ok {
		st = &BuilderStats{
			Builder:         builder,
			CompletedQuests: make([]string, 0),
		}
		builderStatsMap[key] = st
		builderList = append(builderList, st)
	}
	st.TotalEarned += payout
	st.MilestonesWon++
	st.CompletedQuests = append(st.CompletedQuests, "Q#"+strconv.Itoa(questID)+" M#"+strconv.Itoa(milestoneIdx))
}

// ReclaimExpired lets the sponsor reclaim any unspent escrow after the quest deadline passes.
func ReclaimExpired(cur realm, questID int) int64 {
	caller := cur.Previous().Address()
	q := mustGetQuest(questID)

	if caller != q.Sponsor {
		panic("only the sponsor can reclaim expired escrow")
	}
	if q.Status != StatusOpen {
		panic("quest is not open")
	}
	if !time.Now().After(q.Deadline) {
		panic("quest deadline has not yet passed")
	}

	refund := q.RemainingEscrow
	q.RemainingEscrow = 0
	q.Status = StatusReclaimed
	sendEscrowUGNOT(cur, q.Sponsor, refund)

	chain.Emit(
		"QuestReclaimed",
		"quest_id", strconv.Itoa(questID),
		"sponsor", q.Sponsor.String(),
		"refund_ugnot", strconv.FormatInt(refund, 10),
	)
	return refund
}

// CancelUnstarted lets the sponsor cancel an open quest and recover 100% of escrow
// only if zero milestones have been paid out.
func CancelUnstarted(cur realm, questID int) int64 {
	caller := cur.Previous().Address()
	q := mustGetQuest(questID)

	if caller != q.Sponsor {
		panic("only the sponsor can cancel the quest")
	}
	if q.Status != StatusOpen {
		panic("quest is not open")
	}
	if q.PaidOut > 0 {
		panic("cannot cancel quest after a milestone has already been paid")
	}

	refund := q.RemainingEscrow
	q.RemainingEscrow = 0
	q.Status = StatusCancelled
	sendEscrowUGNOT(cur, q.Sponsor, refund)

	chain.Emit(
		"QuestCancelled",
		"quest_id", strconv.Itoa(questID),
		"sponsor", q.Sponsor.String(),
		"refund_ugnot", strconv.FormatInt(refund, 10),
	)
	return refund
}

// Render serves a multi-page gnoweb Markdown portal and a machine-readable JSON stats route.
// Routes:
//   - ""              -> Dashboard & Quest Board
//   - "quest/<id>"    -> Quest detail, milestones, deliverables & review audit log
//   - "builder/<addr>"-> Builder earnings & completed milestone history
//   - "stats"         -> JSON metrics for agents and indexers
func Render(path string) string {
	path = strings.Trim(path, "/")
	if path == "" {
		return renderHome()
	}
	if path == "stats" {
		return renderStatsJSON()
	}
	if strings.HasPrefix(path, "quest/") {
		idStr := strings.TrimPrefix(path, "quest/")
		id, err := strconv.Atoi(idStr)
		if err != nil {
			return "# Invalid Quest ID\n\nExpected `quest/<number>`."
		}
		q, ok := questByID[id]
		if !ok {
			return "# Quest #" + idStr + " Not Found"
		}
		return renderQuest(q)
	}
	if strings.HasPrefix(path, "builder/") {
		addrStr := strings.TrimPrefix(path, "builder/")
		return renderBuilder(addrStr)
	}
	return "# BountyQuorum\n\nUnknown route: `" + path + "`. Try [Home](./) or [Stats](./:stats)."
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# BountyQuorum — On-Chain Milestone Escrow & Quorum Bounty Board\n\n")
	sb.WriteString("Trustless `ugnot` escrow with weighted milestones, multi-reviewer quorum release, and iterative resubmissions.\n\n")

	openCount := 0
	completedCount := 0
	for _, q := range quests {
		if q.Status == StatusOpen {
			openCount++
		} else if q.Status == StatusCompleted {
			completedCount++
		}
	}

	sb.WriteString("## Protocol Metrics\n\n")
	sb.WriteString("| Total Quests | Open | Completed | Total Escrowed | Total Disbursed | Active Builders |\n")
	sb.WriteString("| --- | --- | --- | --- | --- | --- |\n")
	sb.WriteString("| " + strconv.Itoa(len(quests)) +
		" | " + strconv.Itoa(openCount) +
		" | " + strconv.Itoa(completedCount) +
		" | " + quorummath.FormatUGNOT(totalEscrowed) +
		" | " + quorummath.FormatUGNOT(totalDisbursed) +
		" | " + strconv.Itoa(len(builderList)) + " |\n\n")

	sb.WriteString("## Quests\n\n")
	if len(quests) == 0 {
		sb.WriteString("_No quests created yet. Call `CreateQuest` with `-send <amount>ugnot` to fund the first quest!_\n\n")
	} else {
		sb.WriteString("| ID | Title | Status | Escrow | Quorum | Progress | Milestones |\n")
		sb.WriteString("| --- | --- | --- | --- | --- | --- | --- |\n")
		for i := len(quests) - 1; i >= 0; i-- {
			q := quests[i]
			sb.WriteString("| [#" + strconv.Itoa(q.ID) + "](:quest/" + strconv.Itoa(q.ID) + ") | " +
				q.Title + " | `" + q.Status + "` | " +
				quorummath.FormatUGNOT(q.TotalEscrow) + " | " +
				strconv.Itoa(q.Quorum) + "/" + strconv.Itoa(len(q.Reviewers)) + " | " +
				"`" + quorummath.ProgressBar(q.PaidBps, 10) + "` | " +
				strconv.Itoa(len(q.Milestones)) + " |\n")
		}
		sb.WriteString("\n")
	}

	if len(builderList) > 0 {
		sb.WriteString("## Verified Builder Leaderboard\n\n")
		sb.WriteString("| Builder | Milestones Paid | Total Earned |\n")
		sb.WriteString("| --- | --- | --- |\n")
		for _, b := range builderList {
			sb.WriteString("| [" + quorummath.ShortAddr(b.Builder) + "](:builder/" + b.Builder.String() + ") | " +
				strconv.Itoa(b.MilestonesWon) + " | " +
				quorummath.FormatUGNOT(b.TotalEarned) + " |\n")
		}
		sb.WriteString("\n")
	}

	sb.WriteString("---\n")
	sb.WriteString("Machine-readable feed: [`:stats`](:stats)\n")
	return sb.String()
}

func renderQuest(q *Quest) string {
	var sb strings.Builder
	sb.WriteString("# Quest #" + strconv.Itoa(q.ID) + ": " + q.Title + "\n\n")
	if q.Summary != "" {
		sb.WriteString(q.Summary + "\n\n")
	}
	sb.WriteString("- **Status:** `" + q.Status + "`\n")
	sb.WriteString("- **Sponsor:** `" + q.Sponsor.String() + "`\n")
	sb.WriteString("- **Escrow Pool:** " + quorummath.FormatUGNOT(q.TotalEscrow) +
		" (Remaining: " + quorummath.FormatUGNOT(q.RemainingEscrow) +
		", Paid: " + quorummath.FormatUGNOT(q.PaidOut) + ")\n")
	sb.WriteString("- **Progress:** `" + quorummath.ProgressBar(q.PaidBps, 12) + "` (Allocated: " + strconv.Itoa(q.AllocatedBps/100) + "%)\n")
	sb.WriteString("- **Quorum Rule:** " + strconv.Itoa(q.Quorum) + " of " + strconv.Itoa(len(q.Reviewers)) + " reviewers\n")
	sb.WriteString("- **Deadline (UTC):** `" + q.Deadline.UTC().Format(time.RFC3339) + "`\n\n")

	sb.WriteString("## Reviewers\n\n")
	for _, r := range q.Reviewers {
		sb.WriteString("- `" + r.String() + "`\n")
	}
	sb.WriteString("\n")

	sb.WriteString("## Milestones\n\n")
	if len(q.Milestones) == 0 {
		sb.WriteString("_No milestones configured yet. Sponsor can call `AddMilestone`._\n\n")
	} else {
		sb.WriteString("| # | Milestone | Weight | Status | Votes (A/R) | Builder | Deliverable |\n")
		sb.WriteString("| --- | --- | --- | --- | --- | --- | --- |\n")
		for idx, m := range q.Milestones {
			bStr := "-"
			if m.Builder != "" {
				bStr = "[" + quorummath.ShortAddr(m.Builder) + "](:builder/" + m.Builder.String() + ")"
			}
			dStr := "-"
			if m.DeliverableURL != "" {
				dStr = "[proof](" + m.DeliverableURL + ")"
			}
			sb.WriteString("| " + strconv.Itoa(idx) +
				" | " + m.Label +
				" | " + strconv.Itoa(m.WeightBps/100) + "% (" + strconv.Itoa(m.WeightBps) + " bps)" +
				" | `" + m.Status + "`" +
				" | " + strconv.Itoa(m.Approvals) + "/" + strconv.Itoa(m.Rejections) +
				" | " + bStr +
				" | " + dStr + " |\n")
		}
		sb.WriteString("\n")

		sb.WriteString("## Review Audit Log\n\n")
		hasLogs := false
		for idx, m := range q.Milestones {
			for _, rec := range m.History {
				hasLogs = true
				verdict := "REJECT"
				if rec.Approve {
					verdict = "APPROVE"
				}
				sb.WriteString("- **M#" + strconv.Itoa(idx) + " (Round " + strconv.Itoa(rec.Round) + ")** `" +
					verdict + "` by `" + quorummath.ShortAddr(rec.Reviewer) + "`: " + rec.Comment + "\n")
			}
		}
		if !hasLogs {
			sb.WriteString("_No review votes recorded yet._\n")
		}
	}

	sb.WriteString("\n[Back to BountyQuorum Board](./)\n")
	return sb.String()
}

func renderBuilder(addrStr string) string {
	st, ok := builderStatsMap[addrStr]
	if !ok {
		return "# Builder Profile\n\nNo verified milestone payouts yet for `" + addrStr + "`.\n\n[Back](./)"
	}
	var sb strings.Builder
	sb.WriteString("# Builder Profile: `" + st.Builder.String() + "`\n\n")
	sb.WriteString("- **Total Earned:** " + quorummath.FormatUGNOT(st.TotalEarned) + "\n")
	sb.WriteString("- **Milestones Won:** " + strconv.Itoa(st.MilestonesWon) + "\n\n")
	sb.WriteString("## Completed Milestones\n\n")
	for _, item := range st.CompletedQuests {
		sb.WriteString("- " + item + "\n")
	}
	sb.WriteString("\n[Back to Board](./)\n")
	return sb.String()
}

func renderStatsJSON() string {
	return "{\"quests\":" + strconv.Itoa(len(quests)) +
		",\"builders\":" + strconv.Itoa(len(builderList)) +
		",\"total_escrowed_ugnot\":" + strconv.FormatInt(totalEscrowed, 10) +
		",\"total_disbursed_ugnot\":" + strconv.FormatInt(totalDisbursed, 10) + "}"
}

package bountyquorum

import (
	"chain"
	"chain/banker"
	"strings"
	"testing"
	"time"
)

func expectPanic(t *testing.T, substr string, fn func()) {
	t.Helper()
	r := revive(fn)
	if r == nil {
		t.Fatalf("expected abort containing %q, but did not abort", substr)
	}
	got, _ := r.(string)
	if substr != "" && !strings.Contains(got, substr) {
		t.Fatalf("expected abort containing %q, got %q", substr, got)
	}
}

func TestFullQuestLifecycleAndZeroDustPayout(cur realm, t *testing.T) {
	defer resetState()

	pkgAddr := chain.PackageAddress("gno.land/r/g1yf6p3wr7lame69dqx6savrskkpu7qgalsxe5qd/bountyquorum")
	sponsor := chain.PackageAddress("gno.land/r/test/sponsor1")
	rev1 := chain.PackageAddress("gno.land/r/test/rev1")
	rev2 := chain.PackageAddress("gno.land/r/test/rev2")
	rev3 := chain.PackageAddress("gno.land/r/test/rev3")
	builder := chain.PackageAddress("gno.land/r/test/builder1")

	// Seed realm bank balance to simulate chain transfer on CreateQuest + TopUpQuest
	testing.IssueCoins(pkgAddr, chain.Coins{{Denom: "ugnot", Amount: 10000000}})

	// 1. Sponsor creates a 2-of-3 quorum quest funded with 1,000,000 ugnot (1 GNOT)
	testing.SetRealm(testing.NewUserRealm(sponsor))
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 1000000}})
	csv := rev1.String() + "," + rev2.String() + "," + rev3.String()
	qid := CreateQuest(cross(cur), "Build Gno Indexer", "Index on-chain realms into SQLite", csv, 2, 72)
	if qid != 1 {
		t.Fatalf("expected quest id 1, got %d", qid)
	}

	// 2. Community tops up +500,000 ugnot -> total 1,500,000 ugnot
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 500000}})
	TopUpQuest(cross(cur), qid)

	// 3. Sponsor defines 3 milestones summing to 10000 bps (3333 + 3333 + 3334)
	m0 := AddMilestone(cross(cur), qid, "Schema & Parser", 3333)
	m1 := AddMilestone(cross(cur), qid, "Sync Engine", 3333)
	m2 := AddMilestone(cross(cur), qid, "CLI & Docs", 3334)
	if m0 != 0 || m1 != 1 || m2 != 2 {
		t.Fatalf("unexpected milestone indices: %d %d %d", m0, m1, m2)
	}

	// Adding beyond 10000 bps must panic
	expectPanic(t, "exceeds 10000", func() {
		AddMilestone(cross(cur), qid, "Overflow", 1)
	})

	// 4. Builder submits M#0; rev1 rejects, rev2 rejects -> REJECTED -> builder resubmits!
	testing.SetRealm(testing.NewUserRealm(builder))
	SubmitDeliverable(cross(cur), qid, 0, "https://github.com/example/pr/1", "sha256:v1", "initial draft")

	// Builder cannot review own submission
	expectPanic(t, "not a designated reviewer", func() {
		ReviewMilestone(cross(cur), qid, 0, true, "self approve")
	})

	testing.SetRealm(testing.NewUserRealm(rev1))
	out := ReviewMilestone(cross(cur), qid, 0, false, "missing migration tests")
	if out != "pending" {
		t.Fatalf("expected pending after 1 reject in 2-of-3, got %s", out)
	}
	// Double voting in same round must panic
	expectPanic(t, "already voted", func() {
		ReviewMilestone(cross(cur), qid, 0, true, "flip vote")
	})

	testing.SetRealm(testing.NewUserRealm(rev2))
	out = ReviewMilestone(cross(cur), qid, 0, false, "needs error handling")
	if out != "rejected" {
		t.Fatalf("expected rejected after 2 rejects in 2-of-3, got %s", out)
	}

	// 5. Builder fixes and resubmits Round 2 -> rev1 + rev3 approve -> auto-payout!
	testing.SetRealm(testing.NewUserRealm(builder))
	SubmitDeliverable(cross(cur), qid, 0, "https://github.com/example/pr/2", "sha256:v2", "added tests & error handling")

	testing.SetRealm(testing.NewUserRealm(rev1))
	if got := ReviewMilestone(cross(cur), qid, 0, true, "tests pass now"); got != "pending" {
		t.Fatalf("expected pending, got %s", got)
	}
	testing.SetRealm(testing.NewUserRealm(rev3))
	if got := ReviewMilestone(cross(cur), qid, 0, true, "LGTM"); got != "approved" {
		t.Fatalf("expected approved, got %s", got)
	}

	// Complete M#1 and M#2 to verify exact zero-dust payout summing to 1,500,000 ugnot
	for _, idx := range []int{1, 2} {
		testing.SetRealm(testing.NewUserRealm(builder))
		SubmitDeliverable(cross(cur), qid, idx, "https://github.com/example/pr/done", "sha256:ok", "done")
		testing.SetRealm(testing.NewUserRealm(rev1))
		ReviewMilestone(cross(cur), qid, idx, true, "good")
		testing.SetRealm(testing.NewUserRealm(rev2))
		if got := ReviewMilestone(cross(cur), qid, idx, true, "ship it"); got != "approved" {
			t.Fatalf("M#%d expected approved, got %s", idx, got)
		}
	}

	b := banker.NewReadonlyBanker()
	builderBal := b.GetCoins(builder).AmountOf("ugnot")
	if builderBal != 1500000 {
		t.Fatalf("expected builder to receive exact 1500000 ugnot (zero dust), got %d", builderBal)
	}

	q := questByID[qid]
	if q.Status != StatusCompleted || q.RemainingEscrow != 0 || q.PaidOut != 1500000 {
		t.Fatalf("unexpected final quest state: status=%s rem=%d paid=%d", q.Status, q.RemainingEscrow, q.PaidOut)
	}

	// Verify all Render routes produce expected output
	home := Render("")
	if !strings.Contains(home, "Build Gno Indexer") || !strings.Contains(home, "COMPLETED") {
		t.Fatalf("unexpected home render: %s", home)
	}
	detail := Render("quest/1")
	if !strings.Contains(detail, "Schema & Parser") || !strings.Contains(detail, "missing migration tests") {
		t.Fatalf("unexpected quest detail render: %s", detail)
	}
	prof := Render("builder/" + builder.String())
	if !strings.Contains(prof, "1.50 GNOT") || !strings.Contains(prof, "Q#1 M#2") {
		t.Fatalf("unexpected builder render: %s", prof)
	}
	stats := Render("stats")
	if !strings.Contains(stats, "\"total_disbursed_ugnot\":1500000") {
		t.Fatalf("unexpected stats json: %s", stats)
	}
}

func TestReclaimExpiredAndCancelSecurity(cur realm, t *testing.T) {
	defer resetState()

	pkgAddr := chain.PackageAddress("gno.land/r/g1yf6p3wr7lame69dqx6savrskkpu7qgalsxe5qd/bountyquorum")
	sponsor := chain.PackageAddress("gno.land/r/test/sponsor2")
	rev1 := chain.PackageAddress("gno.land/r/test/revA")
	stranger := chain.PackageAddress("gno.land/r/test/stranger")

	testing.IssueCoins(pkgAddr, chain.Coins{{Denom: "ugnot", Amount: 5000000}})

	// Create quest 1 (to test cancel before payout)
	testing.SetRealm(testing.NewUserRealm(sponsor))
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 400000}})
	q1 := CreateQuest(cross(cur), "Cancelable Quest", "Summary", rev1.String(), 1, 24)

	// Stranger cannot cancel
	testing.SetRealm(testing.NewUserRealm(stranger))
	expectPanic(t, "only the sponsor", func() {
		CancelUnstarted(cross(cur), q1)
	})

	// Sponsor cancels cleanly
	testing.SetRealm(testing.NewUserRealm(sponsor))
	refund := CancelUnstarted(cross(cur), q1)
	if refund != 400000 {
		t.Fatalf("expected 400000 refund, got %d", refund)
	}

	// Create quest 2 (to test deadline enforcement & reclaim)
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 600000}})
	q2 := CreateQuest(cross(cur), "Expiring Quest", "Summary", rev1.String(), 1, 1)

	// Early reclaim must panic
	expectPanic(t, "not yet passed", func() {
		ReclaimExpired(cross(cur), q2)
	})

	// Advance time past 1 hour deadline
	testing.SkipHeights(1)
	questByID[q2].Deadline = time.Now().Add(-1 * time.Minute)
	refund2 := ReclaimExpired(cross(cur), q2)
	if refund2 != 600000 {
		t.Fatalf("expected 600000 expired refund, got %d", refund2)
	}
	if questByID[q2].Status != StatusReclaimed {
		t.Fatalf("expected RECLAIMED status, got %s", questByID[q2].Status)
	}
}

// Package groth16 verifies Groth16 zkSNARK proofs on BN254 using the chain's
// native precompiles, with no trusted off-chain verifier in the path.
//
// The standard Groth16 verification equation is
//
//	e(A, B) == e(alpha, beta) * e(vk_x, gamma) * e(C, delta)
//
// and it is checked as one four-pair product equal to the identity in GT:
//
//	e(-A, B) * e(alpha, beta) * e(vk_x, gamma) * e(C, delta) == 1
//
// Verifying keys and proofs use the encodings the precompiles consume: G1 is
// x|y (64 bytes), G2 is x_imag|x_real|y_imag|y_real (128 bytes, EIP-197
// order), scalars are 32 bytes big-endian. Those are the shapes snarkjs and
// circom emit after the conversion performed by this repo's CLI.
//
// Cost and limits a caller must know:
//   - Verification is four pairings plus one G1 scalar multiplication per
//     public input. Cost does not grow with circuit size, only with the number
//     of public inputs.
//   - A is negated with a scalar multiplication by r-1 instead of subtracting
//     its y coordinate from the field modulus. Subtracting by hand would be a
//     second implementation of field arithmetic, with its own bugs.
//   - The precompile reduces scalars modulo the group order, so two different
//     32-byte encodings of the same scalar verify identically. This changes no
//     accepted proof, and it means callers must not treat an accepted public
//     input's bytes as canonical.
package groth16

import (
	"crypto/bn254"
	"encoding/hex"
	"errors"
)

const (
	// g1Size is the precompile's G1 encoding: x|y, 32 bytes each.
	g1Size = 64
	// g2Size is the precompile's G2 encoding: x_imag|x_real|y_imag|y_real.
	g2Size = 128
	// scalarSize is one scalar field element, big-endian.
	scalarSize = 32
	// pairingChunkSize is one (G1, G2) factor as the pairing precompile reads
	// it: the 64-byte G1 point followed by the 128-byte G2 point (EIP-197).
	pairingChunkSize = g1Size + g2Size
	// pairingWordSize is the length of the pairing precompile's boolean answer.
	pairingWordSize = 32
)

// G1 is a point on the BN254 G1 curve in the precompile's 64-byte encoding.
type G1 [g1Size]byte

// G2 is a point on the BN254 G2 curve in the precompile's 128-byte encoding.
type G2 [g2Size]byte

// Scalar is a public input field element in the scalar field, big-endian.
type Scalar [scalarSize]byte

// VerifyingKey holds the circuit-specific verification parameters. IC holds
// len(publicInputs)+1 points: IC[0] is the constant term and IC[i+1] is the
// base for public input i.
type VerifyingKey struct {
	Alpha G1
	Beta  G2
	Gamma G2
	Delta G2
	IC    []G1
}

// Proof is a Groth16 proof: two G1 points and one G2 point.
type Proof struct {
	A G1
	B G2
	C G1
}

var (
	// ErrInvalidProof means the proof is well formed and false.
	ErrInvalidProof = errors.New("groth16: proof does not verify")
	// ErrPublicInputs means the input count does not match the key.
	ErrPublicInputs = errors.New("groth16: public input count does not match verifying key")
	// ErrMalformedKey means the verifying key contains a point the precompile
	// rejects, or a degenerate point that would let the pairing product equal
	// one for the wrong reason.
	ErrMalformedKey = errors.New("groth16: malformed verifying key")
	// ErrMalformedProof means a proof point is rejected by the precompile or is
	// the point at infinity, which no valid Groth16 proof contains.
	ErrMalformedProof = errors.New("groth16: malformed proof")
)

// negateScalarHex is r-1 in the BN254 scalar field, big-endian, where
// r = 0x30644e72e131a029b85045b68181585d2833e84879b9709143e1f593f0000001.
// Multiplying a G1 point by it yields the point's negation.
const negateScalarHex = "30644e72e131a029b85045b68181585d2833e84879b9709143e1f593f0000000"

// minusOne is decoded once at init. The value is a hard-coded constant, so a
// decode failure is a build defect rather than runtime input.
var minusOne = mustScalar(negateScalarHex)

// Verify reports whether proof is valid for vk and the given public inputs.
//
// It returns ErrPublicInputs when len(inputs) != len(vk.IC)-1, ErrMalformedKey
// or ErrMalformedProof when a point is not acceptable to the precompiles or is
// the point at infinity, and ErrInvalidProof when the equation does not hold.
func Verify(vk VerifyingKey, proof Proof, inputs []Scalar) error {
	if len(vk.IC) == 0 || len(inputs) != len(vk.IC)-1 {
		return ErrPublicInputs
	}
	if err := vk.validate(); err != nil {
		return err
	}
	if err := proof.validate(); err != nil {
		return err
	}

	vkx, err := linearCombination(vk.IC, inputs)
	if err != nil {
		return err
	}
	negA, err := negate(proof.A)
	if err != nil {
		return err
	}

	equation := []pairing{
		{g1: negA, g2: proof.B},
		{g1: vk.Alpha, g2: vk.Beta},
		{g1: vkx, g2: vk.Gamma},
		{g1: proof.C, g2: vk.Delta},
	}
	if !pairingIsOne(equation) {
		return ErrInvalidProof
	}
	return nil
}

// validate rejects keys that could make the pairing product equal one for a
// degenerate reason. With every term at infinity the product is one and a zero
// proof would pass, which is why infinity is refused here rather than left to
// the pairing check.
func (vk VerifyingKey) validate() error {
	if isInfinityG1(vk.Alpha) || isInfinityG2(vk.Beta) ||
		isInfinityG2(vk.Gamma) || isInfinityG2(vk.Delta) {
		return ErrMalformedKey
	}
	// A well-formed key still has to be accepted by the precompiles, which is
	// only observable by using it. Adding IC[0] to the identity is the cheapest
	// use that both validates the point and leaves the accumulator unchanged.
	if _, err := add(vk.IC[0], G1{}); err != nil {
		return ErrMalformedKey
	}
	return nil
}

// validate refuses infinity in every proof component. A valid Groth16 proof is
// built from non-zero scalars, so no component is ever the identity.
func (p Proof) validate() error {
	if isInfinityG1(p.A) || isInfinityG2(p.B) || isInfinityG1(p.C) {
		return ErrMalformedProof
	}
	if err := probeG1(p.A); err != nil {
		return ErrMalformedProof
	}
	return nil
}

// linearCombination computes IC[0] + sum(inputs[i] * IC[i+1]).
func linearCombination(ic []G1, inputs []Scalar) (G1, error) {
	acc := ic[0]
	for i := 0; i < len(inputs); i++ {
		term, err := scalarMul(ic[i+1], inputs[i])
		if err != nil {
			return G1{}, ErrMalformedKey
		}
		acc, err = add(acc, term)
		if err != nil {
			return G1{}, ErrMalformedKey
		}
	}
	return acc, nil
}

// pairing is one (G1, G2) factor of the product being checked.
type pairing struct {
	g1 G1
	g2 G2
}

// pairingTrue is the pairing precompile's success answer: one 32-byte word whose
// last byte is 1 and whose other 31 bytes are zero.
var pairingTrue = [pairingWordSize]byte{pairingWordSize - 1: 1}

// pairingIsOne reports whether the product of the given factors equals the
// identity in GT. A short or nil answer means the precompile rejected an input
// point, which is not the identity and therefore not a pass.
func pairingIsOne(factors []pairing) bool {
	out := bn254.PairingCheck(encodePairingInput(factors))
	if len(out) != pairingWordSize {
		return false
	}
	var got [pairingWordSize]byte
	copy(got[:], out)
	return got == pairingTrue
}

// encodePairingInput lays the factors out as the precompile reads them: for each
// factor, the 64-byte G1 point then the 128-byte G2 point, in the given order.
func encodePairingInput(factors []pairing) []byte {
	in := make([]byte, len(factors)*pairingChunkSize)
	for i, f := range factors {
		off := i * pairingChunkSize
		copy(in[off:off+g1Size], f.g1[:])
		copy(in[off+g1Size:off+pairingChunkSize], f.g2[:])
	}
	return in
}

// negate returns -p by multiplying by r-1.
func negate(p G1) (G1, error) {
	return scalarMul(p, minusOne)
}

// add returns p+q. It reports ErrMalformedKey when the precompile rejects
// either point; the proof path remaps that to ErrMalformedProof at its boundary.
func add(p, q G1) (G1, error) {
	in := make([]byte, 0, bn254.G1AddInputSize)
	in = append(in, p[:]...)
	in = append(in, q[:]...)
	return decodeG1(bn254.G1Add(in))
}

// scalarMul returns s*p.
func scalarMul(p G1, s Scalar) (G1, error) {
	in := make([]byte, 0, bn254.G1MulInputSize)
	in = append(in, p[:]...)
	in = append(in, s[:]...)
	return decodeG1(bn254.G1Mul(in))
}

// decodeG1 copies a G1-sized precompile result into the fixed encoding. The
// precompiles answer with nil rather than with an error, so a length other than
// g1Size is the only signal that a point or scalar was rejected.
func decodeG1(out []byte) (G1, error) {
	if len(out) != g1Size {
		return G1{}, ErrMalformedKey
	}
	var p G1
	copy(p[:], out)
	return p, nil
}

// probeG1 makes the precompiles validate a point without changing it.
func probeG1(p G1) error {
	_, err := add(p, G1{})
	return err
}

// isInfinityG1 reports whether p is the all-zero encoding, which the
// precompiles read as the point at infinity.
func isInfinityG1(p G1) bool {
	for i := 0; i < len(p); i++ {
		if p[i] != 0 {
			return false
		}
	}
	return true
}

// isInfinityG2 reports whether p is the all-zero encoding of G2 infinity.
func isInfinityG2(p G2) bool {
	for i := 0; i < len(p); i++ {
		if p[i] != 0 {
			return false
		}
	}
	return true
}

// mustScalar decodes a 32-byte big-endian constant.
func mustScalar(s string) Scalar {
	raw, err := hex.DecodeString(s)
	if err != nil || len(raw) != scalarSize {
		panic("groth16: bad scalar constant")
	}
	var out Scalar
	copy(out[:], raw)
	return out
}
